// Storage can throw in some webviews (blocked cookies/storage, private
// mode). This runs during the very first render, so an unguarded throw
// would crash the whole app to a blank screen — fall back to a key kept
// in memory for the session instead.
let memoryPlayerKey = "";
// Log out writes this tombstone instead of removing the key: a bare
// removeItem() followed by an instant reload did not stick in the
// webview (the session came straight back after the reload — the bug
// Ben reported). While the tombstone is stored, playerKey() hands out
// a session-only in-memory guest key and NEVER overwrites the
// tombstone, so the signed-out state survives reloads. Signing in or
// creating an account overwrites it with the real key.
const SIGNED_OUT_MARKER = "signed-out";
// A brand-new session-only guest key, minted without consulting
// storage at all. Log out resets the shell with this, so signing
// out takes effect even in a webview where the tombstone write
// does not survive (storage snapshot restored on reload, write
// blocked, …) — the in-place reset never depends on storage.
function freshGuestKey(): string {
  memoryPlayerKey = `p-${Math.random().toString(36).slice(2, 10)}-${Date.now().toString(36)}`;
  return memoryPlayerKey;
}
function playerKey(): string {
  try {
    let k = localStorage.getItem("leonida-player-key");
    if (k === SIGNED_OUT_MARKER) {
      if (!memoryPlayerKey) {
        memoryPlayerKey = `p-${Math.random().toString(36).slice(2, 10)}-${Date.now().toString(36)}`;
      }
      return memoryPlayerKey;
    }
    if (!k) {
      // Recover the SAME key from a backup slot before minting a
      // new one (owner's rule, Nov 21 2026: "make sure I stayed
      // signed in until I tell u to remove it"): when a new
      // version lands, the webview can drop the primary storage
      // entry, and minting a fresh key here is what used to sign
      // the owner out — the backup slots below often survive, and
      // recovering the same key keeps this device signed in to
      // its own account. The key stays a random per-device value:
      // nothing shared or fixed is ever handed out.
      k = localStorage.getItem("leonida-player-key-backup");
      if (!k || k === SIGNED_OUT_MARKER) {
        try { k = sessionStorage.getItem("leonida-player-key"); } catch { k = null; }
      }
      if (!k || k === SIGNED_OUT_MARKER) {
        k = `p-${Math.random().toString(36).slice(2, 10)}-${Date.now().toString(36)}`;
      }
      localStorage.setItem("leonida-player-key", k);
    }
    // Keep the backup slots in step with the live key, so any one
    // of them can restore it on a later load.
    try { localStorage.setItem("leonida-player-key-backup", k); } catch { /* ignore */ }
    try { sessionStorage.setItem("leonida-player-key", k); } catch { /* ignore */ }
    return k;
  } catch {
    if (!memoryPlayerKey) {
      memoryPlayerKey = `p-${Math.random().toString(36).slice(2, 10)}-${Date.now().toString(36)}`;
    }
    return memoryPlayerKey;
  }
}


// ---- Saved library ----
// Saves live ON THE ACCOUNT (server-side account_saves rows, see
// getAccountSaves / setAccountSave) so they are never lost: they
// survive a new phone, a cleared browser, and signing back in on
// another device. The localStorage list below is only the fast
// on-device cache — on load the two are merged (anything saved on
// either side is kept and pushed to the account), and every toggle
// writes through to the account immediately.
type SavedKind = "news" | "guide" | "bug" | "clan" | "egg" | "event";
type SavedMap = Record<SavedKind, number[]>;
const SAVED_KINDS: SavedKind[] = ["news", "guide", "bug", "clan", "egg", "event"];
const SAVED_KEY = "viceverse-saved-v1";
function emptySavedMap(): SavedMap {
  return { news: [], guide: [], bug: [], clan: [], egg: [], event: [] };
}
function loadSaved(): SavedMap {
  try {
    const raw = localStorage.getItem(SAVED_KEY);
    if (raw) { const j = JSON.parse(raw) as Partial<SavedMap>; return { news: j.news ?? [], guide: j.guide ?? [], bug: j.bug ?? [], clan: j.clan ?? [], egg: j.egg ?? [], event: j.event ?? [] }; }
  } catch { /* storage blocked */ }
  return emptySavedMap();
}
function persistSaved(m: SavedMap) { try { localStorage.setItem(SAVED_KEY, JSON.stringify(m)); } catch { /* ignore */ } }
function useSaved(playerKey: string) {
  const [saved, setSaved] = useState<SavedMap>(() => loadSaved());
  const syncedRef = useRef(false);
  useEffect(() => {
    if (!playerKey || syncedRef.current) return;
    syncedRef.current = true;
    let cancelled = false;
    api.getAccountSaves({ playerKey }).then((res) => {
      if (cancelled) return;
      const serverMap = emptySavedMap();
      for (const item of res.items) {
        if ((SAVED_KINDS as string[]).includes(item.kind)) {
          const kind = item.kind as SavedKind;
          if (!serverMap[kind].includes(item.refId)) serverMap[kind].push(item.refId);
        }
      }
      setSaved((prev) => {
        const merged = emptySavedMap();
        for (const kind of SAVED_KINDS) {
          merged[kind] = [...new Set([...serverMap[kind], ...prev[kind]])];
          // Anything only on this device so far is pushed UP to the
          // account, so older device saves join the account too.
          for (const id of prev[kind]) {
            if (!serverMap[kind].includes(id)) {
              api.setAccountSave({ playerKey, kind, refId: id, saved: true }).catch(() => { /* retried on next toggle */ });
            }
          }
        }
        persistSaved(merged);
        return merged;
      });
    }).catch(() => { /* account unreachable — the device cache still works */ });
    return () => { cancelled = true; };
  }, [playerKey]);
  const toggle = (kind: SavedKind, id: number) => {
    const nowSaved = !saved[kind].includes(id);
    setSaved((prev) => {
      const list = prev[kind].includes(id) ? prev[kind].filter((x) => x !== id) : [...prev[kind], id];
      const next = { ...prev, [kind]: list };
      persistSaved(next);
      return next;
    });
    if (playerKey) {
      api.setAccountSave({ playerKey, kind, refId: id, saved: nowSaved }).catch(() => { /* device cache already updated */ });
    }
  };
  const has = (kind: SavedKind, id: number) => saved[kind].includes(id);
  return { saved, toggle, has };
}
function SaveButton({ saved, onToggle, label }: { saved: boolean; onToggle: () => void; label: string }) {
  // One toggle everywhere (owner's rule): Save puts the item in the
  // library, pressing the same button again — now lit teal with a
  // filled bookmark, the same saved look as the Feed / Clips
  // bookmark — takes it back out. Every Save control in the app is
  // this button, so press-again-to-unsave holds on every tab.
  return (
    <button type="button" className="btn-ghost" style={{ minHeight: 40, padding: "6px 14px", fontSize: 13, ...(saved ? { borderColor: "var(--accent2)", color: "var(--accent2)", background: "var(--accent2-soft)" } : {}) }} aria-pressed={saved} aria-label={`${saved ? "Remove from Saved:" : "Save:"} ${label}`} onClick={onToggle}>
      <svg width="13" height="13" viewBox="0 0 24 24" fill={saved ? "currentColor" : "none"} stroke="currentColor" strokeWidth="2" aria-hidden="true"><path d="M6 3h12a1 1 0 0 1 1 1v17l-7-4-7 4V4a1 1 0 0 1 1-1z" /></svg>
      {saved ? "Saved" : "Save"}
    </button>
  );
}

// ---- Tracked goals: news stories and events the player chose to
// follow from News / Events. They surface in Goals with a done tick,
// an optional reminder date, and the link back to the official post.
// Like the Saved library, tracked goals are stored ON THE ACCOUNT
// (account_saves rows of kind "tracked", the full snapshot as JSON in
// meta) so they are never lost with a device; localStorage is the
// on-device cache, merged with the account on load.
type TrackedGoal = { key: string; kind: "news" | "event" | "feed"; refId: number; title: string; date: string; url: string; done: boolean; remind: string };
const TRACKED_KEY = "viceverse-tracked-goals-v1";
function loadTracked(): TrackedGoal[] {
  try {
    const raw = localStorage.getItem(TRACKED_KEY);
    if (raw) { const j = JSON.parse(raw) as TrackedGoal[]; if (Array.isArray(j)) return j; }
  } catch { /* storage blocked */ }
  return [];
}
function trackedMeta(g: TrackedGoal): string {
  return JSON.stringify({ kind: g.kind, refId: g.refId, title: g.title, date: g.date, url: g.url, done: g.done, remind: g.remind });
}
function useTrackedGoals(playerKey: string) {
  const [items, setItems] = useState<TrackedGoal[]>(() => loadTracked());
  const syncedRef = useRef(false);
  const persist = (next: TrackedGoal[]) => {
    setItems(next);
    try { localStorage.setItem(TRACKED_KEY, JSON.stringify(next)); } catch { /* ignore */ }
  };
  useEffect(() => {
    if (!playerKey || syncedRef.current) return;
    syncedRef.current = true;
    let cancelled = false;
    api.getAccountSaves({ playerKey }).then((res) => {
      if (cancelled) return;
      const serverItems: TrackedGoal[] = [];
      for (const item of res.items) {
        if (item.kind !== "tracked" || !item.meta) continue;
        try {
          const m = JSON.parse(item.meta) as Omit<TrackedGoal, "key">;
          if (m && (m.kind === "news" || m.kind === "event" || m.kind === "feed") && typeof m.refId === "number") {
            serverItems.push({ ...m, key: `${m.kind}:${m.refId}`, title: m.title ?? "", date: m.date ?? "", url: m.url ?? "", done: Boolean(m.done), remind: m.remind ?? "" });
          }
        } catch { /* skip a malformed snapshot */ }
      }
      setItems((prev) => {
        const byKey = new Map<string, TrackedGoal>();
        for (const g of serverItems) byKey.set(g.key, g);
        for (const g of prev) {
          if (!byKey.has(g.key)) {
            byKey.set(g.key, g);
            api.setAccountSave({ playerKey, kind: "tracked", refId: g.refId, saved: true, meta: trackedMeta(g) }).catch(() => { /* retried on next change */ });
          }
        }
        const merged = [...byKey.values()];
        try { localStorage.setItem(TRACKED_KEY, JSON.stringify(merged)); } catch { /* ignore */ }
        return merged;
      });
    }).catch(() => { /* account unreachable — the device cache still works */ });
    return () => { cancelled = true; };
  }, [playerKey]);
  const pushSave = (g: TrackedGoal) => {
    if (playerKey) api.setAccountSave({ playerKey, kind: "tracked", refId: g.refId, saved: true, meta: trackedMeta(g) }).catch(() => { /* device cache already updated */ });
  };
  const pushRemove = (g: TrackedGoal) => {
    if (playerKey) api.setAccountSave({ playerKey, kind: "tracked", refId: g.refId, saved: false }).catch(() => { /* device cache already updated */ });
  };
  const has = (kind: "news" | "event" | "feed", refId: number) => items.some((i) => i.kind === kind && i.refId === refId);
  const toggle = (g: { kind: "news" | "event" | "feed"; refId: number; title: string; date: string; url: string }) => {
    const key = `${g.kind}:${g.refId}`;
    const existing = items.find((i) => i.key === key);
    if (existing) { pushRemove(existing); persist(items.filter((i) => i.key !== key)); }
    else { const full: TrackedGoal = { ...g, key, done: false, remind: "" }; pushSave(full); persist([...items, full]); }
  };
  const setDone = (key: string, done: boolean) => {
    const next = items.map((i) => (i.key === key ? { ...i, done } : i));
    const changed = next.find((i) => i.key === key);
    if (changed) pushSave(changed);
    persist(next);
  };
  const setRemind = (key: string, remind: string) => {
    const next = items.map((i) => (i.key === key ? { ...i, remind } : i));
    const changed = next.find((i) => i.key === key);
    if (changed) pushSave(changed);
    persist(next);
  };
  const remove = (key: string) => {
    const existing = items.find((i) => i.key === key);
    if (existing) pushRemove(existing);
    persist(items.filter((i) => i.key !== key));
  };
  return { items, has, toggle, setDone, setRemind, remove };
}

