type NewsRow = ApiResponse<typeof api, "listNews">["items"][number];
function newsSourceType(n: NewsRow): string {
  const u = (n.sourceUrl || "").toLowerCase();
  const sn = (n.sourceName || "").toLowerCase();
  const t = `${n.title} ${n.summary}`.toLowerCase();
  if (u.includes("youtube") || u.includes("youtu.be")) return "Videos";
  if (u.includes("x.com") || u.includes("twitter")) return "Twitter / X";
  if (t.includes("earnings") || t.includes("investor") || sn.includes("take-two")) return "Earnings Calls";
  if (u.includes("rockstargames.com") || n.category === "Official" || n.category === "Patch") return "Newswire";
  return "Community";
}

