  const shownPins = MAP_SCHEMATIC_PINS.filter((pin) => { const cat = MAP_CAT_BY_ID[pin.catId]; return cat && !hiddenCats.includes(cat.group) && !hiddenPinCats.includes(cat.id); }).length;
  const pinKeyFor = (catId: string, x: number, y: number) => `${catId}@${x.toFixed(1)},${y.toFixed(1)}`;
  const toggleCat = (name: string) => setHiddenCats((prev) => (prev.includes(name) ? prev.filter((c) => c !== name) : [...prev, name]));
  const [confirmClear, setConfirmClear] = useState(false);
  const mapCardRef = useRef<HTMLDivElement | null>(null);
  const [mapOpen, setMapOpen] = useState(() => { const v = mapLaunchOpen; mapLaunchOpen = false; return v; });
  const openFullMap = () => { setMapOpen(true); };
  /* Back from the full-screen map screen: close the screen, and
     when the shell has a back-stack entry (the map was opened as
     a detail from another page — e.g. Database) hand back to it,
     so the player lands on that page at the exact scroll spot
     they left. With no entry, closing simply reveals the map
     page underneath, untouched — the page is scroll-locked for
     as long as the map screen is open. */
  const closeMap = () => {
    setMapOpen(false);
    if (onBack) onBack();
  };
  /* While the full-screen map is open it owns the viewport: the
     page behind cannot scroll (so Back returns to the same
     place), and Esc closes the map screen. */
  useEffect(() => {
    if (!mapOpen) return;
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") setMapOpen(false); };
    window.addEventListener("keydown", onKey);
    return () => { document.body.style.overflow = prev; window.removeEventListener("keydown", onKey); };
  }, [mapOpen]);
  const toggleFullscreen = () => {
    try {
      if (document.fullscreenElement) { void document.exitFullscreen(); }
      else if (mapCardRef.current) { void mapCardRef.current.requestFullscreen(); }
    } catch { /* fullscreen is blocked in some embeds — the map still works inline */ }
  };
  const dragRef = useRef<{ px: number; py: number; ox: number; oy: number; moved: boolean } | null>(null);
