// Avatars are plain now: Avatar Effects were removed completely
// (owner's direction, Nov 21 2026) — a member's avatar is their own
// uploaded profile picture, or the default silhouette below. No
// effect layers, rims or overlays render anywhere.

// Instagram-style DEFAULT profile picture: a grey silhouette person
// on a light grey circle. Every account that has not set a picture —
// every new account, until the player uploads their own picture or
// equips a catalogue avatar — shows this everywhere an avatar appears
// (profile, Feed, crew roster, directory, comments, messages).
// The moment they upload their own picture (Edit profile → Upload
// your own picture) or equip an avatar, avatarUrl is set and that
// picture replaces the default everywhere; they can change it again
// anytime the same way. Never a coloured initial letter.
function DefaultAvatarSilhouette() {
  return (
    <svg viewBox="0 0 100 100" className="h-full w-full" aria-hidden="true" focusable="false">
      <rect width="100" height="100" fill="#d9d9de" />
      <circle cx="50" cy="37" r="16.5" fill="#9a9aa2" />
      <path d="M17 100 C17 74 31 62 50 62 C69 62 83 74 83 100 Z" fill="#9a9aa2" />
    </svg>
  );
}

function CosmeticAvatar({ name, size = 44, role, avatarUrl = "", eager = false }: { name: string; size?: number; role?: string; avatarUrl?: string; eager?: boolean }) {
  const bg = role ? (ROLE_COLORS[role] ?? avatarColor(name)) : avatarColor(name);
  return (
    <span
      className="avatar-fx-wrap"
      style={{ width: size, height: size }}
      role="img"
      aria-label={avatarUrl ? `${name} avatar` : `${name} — default profile picture`}
    >
      <span
        className="relative inline-flex h-full w-full flex-none items-center justify-center overflow-hidden rounded-full"
        style={{
          background: avatarUrl ? bg : "#d9d9de",
          border: "2px solid rgba(255,255,255,0.25)",
        }}
      >
        {avatarUrl ? (
          <img decoding="async" src={avatarUrl} alt="" className="avatar-anim h-full w-full object-cover" loading={eager ? "eager" : "lazy"} {...(eager ? { fetchPriority: "high" as const } : {})} />
        ) : (
          <DefaultAvatarSilhouette />
        )}
      </span>
    </span>
  );
}


/* Crew Leaderboard visibility (owner's direction): the Crew
   Leaderboard is REMOVED for now — hidden from Home, from Crews and
   from the Leaderboard page — but nothing is deleted. The
   clanRankings action, every crew's Rank Points and standings, the
   Home bar-chart card, the Crews entry card and the full
   Leaderboard page below (season countdown, Global / Local /
   PlayStation / Xbox boards, the PlayStation / Xbox
   linked-account locking and platform default, search, season
   graph) all stay in place behind this one switch. Flip it to true
   and the Crew Leaderboard comes back exactly as it was. */
const CREW_LEADERBOARD_ENABLED = false;

type RankedClan = ApiResponse<typeof api, "clanRankings">["global"][number];
type RankBoard = "global" | "local" | "playstation" | "xbox";

const RANK_BOARDS: { id: RankBoard; icon: string; label: string }[] = [
  { id: "global", icon: "", label: "Global" },
  { id: "local", icon: "", label: "Local" },
  { id: "playstation", icon: "", label: "PlayStation" },
  { id: "xbox", icon: "XB", label: "Xbox" },
];
/* Rank badge colours for the leaderboard's top 3 (owner's model:
   the Clash Royale "Top Royales" list) — 1 gold, 2 silver,
   3 bronze, drawn as ViceSunshine gradients, never copied art.
   Every other rank sits on a plain dark tile. */
function rankBadgeStyle(rank: number): { background: string; color: string; boxShadow?: string } {
  if (rank === 1) return { background: "linear-gradient(160deg, #FFE066, #FFB03A 60%, #F08C1E)", color: "#231303", boxShadow: "0 0 16px rgba(255,176,58,0.35)" };
  if (rank === 2) return { background: "linear-gradient(160deg, #F4F6FB, #B9C0D0 60%, #8E97AB)", color: "#14161f", boxShadow: "0 0 12px rgba(200,208,226,0.25)" };
  if (rank === 3) return { background: "linear-gradient(160deg, #F2B183, #C97A3D 60%, #9E5A24)", color: "#221102", boxShadow: "0 0 12px rgba(201,122,61,0.3)" };
  return { background: "var(--surface)", color: "var(--text)" };
}

/* The full Crew Leaderboard page (owner's direction, modelled on
   the Clash Royale "Top Royales" list — layout only, in
   ViceSunshine's own dark-neon style, no copied art or styling):
   where Home's Crew Leaderboard card leads. Category buttons on
   top — Global, Local, PlayStation, Xbox — then a clean ranked
   list, each row carrying a big rank number (1 gold, 2 silver,
   3 bronze), the trend against last season's finish (= when it
   holds, an arrow with the places moved when it climbs or drops),
   the crew emblem and name, its Members count (e.g. 50/50) and its
   season points on the right. Every category tracks the Top 1000
   crews, searchable, with the Compare tool and past-season
   winners below. The board re-reads every 30 seconds, so ranks
   update on their own. Tapping a row opens that crew's home (via
   the "vv-open-crew" handoff into Crews). */
type SeasonGraph = ApiResponse<typeof api, "clanRankings">["graphs"]["global"];
const SEASON_LINE_FALLBACKS = ["#FF2E88", "#00E5CC", "#9D4EDD", "#FFB03A", "#4ade80"];
function seasonLineColor(color: string, idx: number): string {
  return /^#[0-9a-fA-F]{6}$/.test(color) ? color : (SEASON_LINE_FALLBACKS[idx] ?? "#FF2E88");
}
/* Season points lines: the top crews' cumulative season points at
   each weekly checkpoint, one calm line per crew in its own colour.
   On the leaderboard page this chart sits at the very BOTTOM, after
   the Top 1000 list (owner's direction) — never above the list. */
function SeasonLines({ graph, maxCrews = 5 }: { graph: SeasonGraph; maxCrews?: number }) {
  const crews = graph.crews.slice(0, maxCrews);
  const W = 720;
  const H = 190;
  const PL = 44;
  const PR = 12;
  const PT = 14;
  const PB = 22;
  const plotW = W - PL - PR;
  const plotH = H - PT - PB;
  const max = Math.max(1, ...crews.flatMap((c) => c.values));
  const n = Math.max(2, graph.labels.length);
  const x = (i: number) => PL + (i / (n - 1)) * plotW;
  const y = (v: number) => PT + (1 - v / max) * plotH;
  const gridVals = [...new Set([0, 0.5, 1].map((f) => Math.round(max * f)))];
  return (
    <div>
      <svg viewBox={`0 0 ${W} ${H}`} className="block w-full" role="img" aria-label={`Season points over time for the top ${crews.length} crews`}>
        {gridVals.map((v) => (
          <g key={v}>
            <line x1={PL} x2={W - PR} y1={y(v)} y2={y(v)} stroke="rgba(255,255,255,0.12)" strokeWidth="1" strokeDasharray="1 6" />
            <text x={PL - 7} y={y(v) + 3.5} textAnchor="end" fontSize="10.5" fill="#7e7a90">{v.toLocaleString()}</text>
          </g>
        ))}
        {graph.labels.map((l, i) => (
          <text key={`${l}-${i}`} x={x(i)} y={H - 6} textAnchor="middle" fontSize="10.5" fill="#7e7a90">{l}</text>
        ))}
        {crews.map((c, ci) => (
          <polyline key={c.id} fill="none" stroke={seasonLineColor(c.color, ci)} strokeWidth="2.4" strokeLinejoin="round" strokeLinecap="round" points={c.values.map((v, i) => `${x(i)},${y(v)}`).join(" ")} />
        ))}
      </svg>
      <div className="mt-2 flex flex-wrap gap-x-4 gap-y-1.5">
        {crews.map((c, ci) => (
          <span key={c.id} className="inline-flex items-center gap-1.5 text-[12px] font-bold">
            <span className="inline-block h-[3px] w-4 rounded-full" style={{ background: seasonLineColor(c.color, ci) }} aria-hidden="true" />
            {c.name}
          </span>
        ))}
      </div>
    </div>
  );
}

// Live season-end countdown for the Leaderboard: ticks every second
// toward the end of the current season (the last day of the season
// month, from clanRankings' seasonEndsAt), then the season resets.
function SeasonCountdown({ endsAt, label }: { endsAt: string; label: string }) {
  const [nowMs, setNowMs] = useState(() => Date.now());
  useEffect(() => {
    const t = window.setInterval(() => setNowMs(Date.now()), 1000);
    return () => window.clearInterval(t);
  }, []);
  const target = new Date(`${endsAt}T23:59:59`).getTime();
  const diff = Math.max(0, target - nowMs);
  const days = Math.floor(diff / 86400000);
  const hours = Math.floor((diff % 86400000) / 3600000);
  const mins = Math.floor((diff % 3600000) / 60000);
  const secs = Math.floor((diff % 60000) / 1000);
  const pad = (n: number) => String(n).padStart(2, "0");
  const text = diff <= 0
    ? "Season ending now — the new season starts today"
    : `Season ends in ${days > 0 ? `${days}d ` : ""}${pad(hours)}h ${pad(mins)}m ${pad(secs)}s`;
  return (
    <p className="mt-2 flex flex-wrap items-center gap-2 text-[13px] font-bold" role="timer" aria-label={`${label} — ${text}`}>
      <span className="rounded-full px-2.5 py-1" style={{ background: "var(--surface2)", border: "1px solid var(--border)", color: "var(--accent2)" }}>{label}</span>
      <span className="tabular-nums text-[var(--text)]">{text}</span>
    </p>
  );
}

/* Small padlock glyph for the Leaderboard's locked platform tabs
   (owner's direction): PlayStation / Xbox boards unlock only when
   that platform account is linked on the viewer's profile. */
function BoardLockGlyph({ size = 15 }: { size?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" className="flex-none">
      <rect x="4.5" y="10.5" width="15" height="10" rx="2" />
      <path d="M8 10.5V7.5a4 4 0 0 1 8 0v3" />
      <circle cx="12" cy="15.5" r="1.3" fill="currentColor" stroke="none" />
    </svg>
  );
}

function LeaderboardView({
  playerKey,
  go,
  onBack,
}: {
  playerKey: string;
  go: (t: Tab) => void;
  onBack?: () => void;
}) {
  const [board, setBoard] = useState<RankBoard>("global");
  const [boardSearch, setBoardSearch] = useState("");
  const [shown, setShown] = useState(100);
  const openCrew = (id: number) => {
    try { window.localStorage.setItem("vv-open-crew", String(id)); } catch { /* storage unavailable */ }
    go("clans");
  };
  const profile = useQuery({
    queryKey: ["profile", playerKey],
    queryFn: () => api.getProfile({ playerKey }),
  });
  const region = profile.data?.profile?.region ?? "";
  /* Platform locking (owner's direction): the PlayStation board is
     unlocked only when a PlayStation / PSN account is linked on the
     viewer's profile, and the Xbox board only when an Xbox account
     is linked. Linked only PS → Xbox locked; linked only Xbox →
     PlayStation locked; both linked → both open; neither → both
     locked. Global and Local stay open to everyone. While the
     profile is still loading nothing is locked yet, so an unlocked
     board never flashes a lock panel. */
  const myProfile = profile.data?.profile ?? null;
  const linksKnown = profile.data !== undefined;
  const hasPsn = !!myProfile?.psnId?.trim();
  const hasXbox = !!myProfile?.xboxId?.trim();
  const boardLocked = (b: RankBoard): boolean => {
    if (!linksKnown) return false;
    if (b === "playstation") return !hasPsn;
    if (b === "xbox") return !hasXbox;
    return false;
  };
  const activeLocked = boardLocked(board);
  /* Default board (owner's direction): the Leaderboard opens on the
     platform the player linked / chose when they made their account
     — a PS user opens on PlayStation, an Xbox user on Xbox. Applied
     once, the first time the profile lands; with neither platform
     linked it stays on Global. */
  const defaultBoardApplied = useRef(false);
  useEffect(() => {
    if (defaultBoardApplied.current || profile.data === undefined) return;
    defaultBoardApplied.current = true;
    const p = profile.data.profile;
    const ps = !!p?.psnId?.trim();
    const xb = !!p?.xboxId?.trim();
    if (!ps && !xb) return;
    let target: RankBoard = "global";
    if (p?.platform === "Xbox" && xb) target = "xbox";
    else if (p?.platform === "PS5" && ps) target = "playstation";
    else if (ps && !xb) target = "playstation";
    else if (xb && !ps) target = "xbox";
    else if (ps && xb) target = p?.platform === "Xbox" ? "xbox" : "playstation";
    if (target !== "global") setBoard(target);
  }, [profile.data]);
  const rankings = useQuery({
    queryKey: ["clanRankings", region],
    queryFn: () => api.clanRankings({ region }),
    enabled: CREW_LEADERBOARD_ENABLED,
    // Live: the board re-reads every 30 seconds while the page is
    // open, so ranks and points move on their own.
    refetchInterval: 30000,
  });
  const data = rankings.data;
  const active: RankedClan[] = data ? data[board] : [];
  // The full board, capped at the Top 1000 (owner's direction):
  // every category — Global, Local, PlayStation, Xbox — tracks
  // its own Top 1000 crews, searchable by crew name or tag.
  // Rows render in pages of 100 ("Show more") so a full board
  // stays fast on a phone; search always scans the whole 1000.
  const top1000 = active.slice(0, 1000);
  const boardQuery = boardSearch.trim().toLowerCase();
  const visible = boardQuery
    ? top1000.filter((c) => c.name.toLowerCase().includes(boardQuery) || c.tag.toLowerCase().includes(boardQuery))
    : top1000.slice(0, shown);

  /* Removed for now (owner's direction): while
     CREW_LEADERBOARD_ENABLED is off, the Leaderboard page shows
     only this note — the full board (countdown, category tabs with
     the PlayStation / Xbox linked-account locking, Top 1000 list,
     search, season graph) stays implemented directly below and
     returns exactly as it was when the switch flips back on. Crew
     Rank Points keep counting in the background either way. */
  if (!CREW_LEADERBOARD_ENABLED) {
    return (
      <div>
        <button type="button" className="btn-ghost btn-compact" onClick={() => (onBack ? onBack() : go("home"))} aria-label="Back to where you were">← Back</button>
        <h2 className="font-display mt-4 text-2xl leading-tight">Leaderboard</h2>
        <div className="card mt-4 p-6 text-center">
          <p className="font-display text-lg font-extrabold">The Crew Leaderboard is off for now</p>
          <p className="mx-auto mt-1.5 max-w-md text-sm leading-relaxed text-[var(--dim)]">
            Crew rankings are taking a break. Your crew still earns Rank Points from everything you do in ViceSunshine, and every point is kept — nothing is lost while the board is away.
          </p>
          <button type="button" className="btn-game mt-4" onClick={() => go("clans")} aria-label="Open Crews — browse crews and open your crew home">
            Browse crews
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="leaderboard-view">
      <button type="button" className="btn-ghost btn-compact" onClick={() => (onBack ? onBack() : go("home"))} aria-label="Back to where you were">← Back</button>
      <h2 className="font-display mt-3 text-xl leading-tight sm:mt-4 sm:text-2xl">Crew Leaderboard</h2>
      {/* Season-end countdown (owner's direction): one compact line
          under the title — the only thing above the list. It ticks
          every second toward the end of the current season month,
          when the board resets and the season rewards land. */}
      {data && <SeasonCountdown endsAt={data.seasonEndsAt} label={data.seasonLabel} />}
      {/* Category buttons (owner's model: the big Global / Local
          buttons at the top of the Top Royales list) — chunky
          pills, the active category lit in the ViceSunshine
          pink-to-purple gradient. */}
      <div className="mt-4 grid grid-cols-2 gap-2 sm:grid-cols-4" role="tablist" aria-label="Leaderboard categories">
        {RANK_BOARDS.map((b) => {
          const isActive = board === b.id;
          const locked = boardLocked(b.id);
          const lockHint = b.id === "playstation"
            ? "PlayStation leaderboard — locked. Link a PlayStation / PSN account on your profile to unlock it"
            : "Xbox leaderboard — locked. Link an Xbox account on your profile to unlock it";
          return (
            <button
              key={b.id}
              type="button"
              role="tab"
              aria-selected={isActive}
              aria-label={locked ? lockHint : `${b.label} leaderboard`}
              onClick={() => { setBoard(b.id); setShown(100); }}
              className="rounded-2xl px-3 text-[15px] font-extrabold tracking-tight"
              style={{
                minHeight: 52,
                background: isActive ? "linear-gradient(120deg, var(--accent), #9D4EDD)" : "var(--surface2)",
                color: isActive ? "#fff" : "var(--text)",
                border: `1px solid ${isActive ? "transparent" : "var(--border)"}`,
                boxShadow: isActive ? "0 6px 22px rgba(255,46,136,0.35)" : undefined,
                opacity: locked && !isActive ? 0.72 : undefined,
              }}
            >
              <span className="inline-flex items-center justify-center gap-1.5">
                {locked && <BoardLockGlyph size={14} />}
                {b.id === "local" && region ? `Local · ${region}` : b.label}
                {locked && <span className="text-[10px] font-extrabold uppercase tracking-widest opacity-80">Locked</span>}
              </span>
            </button>
          );
        })}
      </div>
      <div className="card mt-4 overflow-hidden">
        <div className="p-4">
        {activeLocked ? (
          <div className="p-3 text-center">
            <span className="mx-auto flex h-14 w-14 items-center justify-center rounded-full" style={{ background: "var(--surface2)", border: "1px solid var(--border)", color: "var(--dim)" }}>
              <BoardLockGlyph size={24} />
            </span>
            <p className="mt-3 font-display text-lg font-extrabold">{board === "playstation" ? "PlayStation" : "Xbox"} rankings are locked</p>
            <p className="mx-auto mt-1 max-w-md text-sm leading-relaxed text-[var(--dim)]">
              {board === "playstation"
                ? "The PlayStation board only opens for players with a PlayStation / PSN account linked. Link your PSN account and your PlayStation ranking shows here."
                : "The Xbox board only opens for players with an Xbox account linked. Link your Xbox gamertag and your Xbox ranking shows here."}
              {board === "playstation" && hasXbox && !hasPsn ? " You've linked Xbox — link PlayStation too and this board opens." : ""}
              {board === "xbox" && hasPsn && !hasXbox ? " You've linked PlayStation — link Xbox too and this board opens." : ""}
              {" "}Global and Local stay open to everyone.
            </p>
            <button
              type="button"
              className="btn-game mt-3"
              onClick={() => go("profile")}
              aria-label={board === "playstation" ? "Go to my profile to link a PlayStation / PSN account and unlock the PlayStation leaderboard" : "Go to my profile to link an Xbox account and unlock the Xbox leaderboard"}
            >
              {board === "playstation" ? "Link a PlayStation account" : "Link an Xbox account"}
            </button>
          </div>
        ) : (
        <>
        {data && top1000.length > 0 && (
          <div className="mb-3 flex flex-wrap items-center gap-2.5">
            <span className="trophy-pill">Top {top1000.length} of 1000</span>
            <input
              className="field min-w-[180px] flex-1"
              type="search"
              value={boardSearch}
              onChange={(e) => setBoardSearch(e.target.value)}
              placeholder="Search the Top 1000 crews…"
              aria-label="Search the Top 1000 crews"
              style={{ minHeight: 42 }}
            />
            {boardQuery && <span className="text-[12.5px] font-semibold text-[var(--dim)]">{visible.length} found</span>}
          </div>
        )}
        {rankings.isPending && <p className="text-sm text-[var(--dim)]">Loading rankings…</p>}
        {data && active.length === 0 && board === "local" && !region && (
          <div className="p-3 text-center">
            <p className="text-4xl" aria-hidden="true"></p>
            <p className="mt-2 font-bold">No region on your profile yet</p>
            <p className="mt-1 text-sm text-[var(--dim)]">Local ranking shows crews in your region. Add your region to your profile and your local board appears here.</p>
            <button type="button" className="btn-game mt-3" onClick={() => go("profile")}> Set my region</button>
          </div>
        )}
        {data && active.length === 0 && board === "local" && region && (
          <div className="p-3 text-center">
            <p className="text-4xl" aria-hidden="true"></p>
            <p className="mt-2 font-bold">No crews in {region} yet</p>
            <p className="mt-1 text-sm text-[var(--dim)]">Found a crew in your region and it takes the local #1 spot.</p>
          </div>
        )}
        {data && active.length === 0 && board !== "local" && (
          <div className="p-3 text-center">
            <p className="text-4xl" aria-hidden="true"></p>
            <p className="mt-2 font-bold">No crews ranked yet</p>
            <p className="mt-1 text-sm text-[var(--dim)]">The first crew founded takes the #1 spot on this board.</p>
          </div>
        )}
        {data && boardQuery && visible.length === 0 && top1000.length > 0 && (
          <p className="p-3 text-center text-sm text-[var(--dim)]">No crew in the Top 1000 matches “{boardSearch.trim()}” on this board.</p>
        )}
        <ol className="grid gap-2">
          {visible.map((c) => {
            const delta = c.prevRank > 0 ? Math.abs(c.prevRank - c.rank) : 0;
            return (
              <li key={c.id}>
                <button
                  type="button"
                  className="block w-full rounded-2xl border p-3 text-left"
                  style={{
                    background:
                      c.rank === 1
                        ? "linear-gradient(120deg, rgba(255,176,58,0.16), var(--surface2) 55%)"
                        : c.rank === 2
                          ? "linear-gradient(120deg, rgba(200,208,226,0.13), var(--surface2) 55%)"
                          : c.rank === 3
                            ? "linear-gradient(120deg, rgba(201,122,61,0.15), var(--surface2) 55%)"
                            : "var(--surface2)",
                    borderColor: c.rank === 1 ? "var(--amber)" : "var(--border)",
                  }}
                  onClick={() => openCrew(c.id)}
                  aria-label={`Rank ${c.rank}: ${c.name}, ${c.memberCount} members (unlimited), ${c.effectiveSeasonPoints} season points — open crew home`}
                >
                  {/* The crew's banner as a strip across the top of
                      its row — every crew shows its own picture
                      (emblem, below) and its own banner here on the
                      Leaderboard, just like on its crew profile. The
                      banner is the crew's equipped calling card; a
                      crew that has not equipped one yet still gets
                      its own banner strip in its crew colour with its
                      name on it, until its Leader picks a card. */}
                  {c.callingCard && cardDesignOf(c.callingCard) ? (
                    <span className="relative mb-2.5 block h-[42px] w-full overflow-hidden rounded-lg" style={{ background: cardDesignOf(c.callingCard)?.background }} aria-hidden="true">
                      <CardSceneArt scene={cardDesignOf(c.callingCard)?.scene ?? "skyline"} animated={false} />
                      <span className="absolute bottom-1.5 left-2.5 font-display text-[11px] font-extrabold uppercase tracking-widest text-white" style={{ textShadow: "0 1px 6px rgba(0,0,0,0.75)" }}>
                        {cardDesignOf(c.callingCard)?.title}
                      </span>
                    </span>
                  ) : (
                    <span className="relative mb-2.5 block h-[42px] w-full overflow-hidden rounded-lg" style={{ background: `linear-gradient(120deg, ${c.color} 0%, ${c.color}55 45%, rgba(11,11,20,0.92) 100%)` }} aria-hidden="true">
                      <span className="absolute bottom-1.5 left-2.5 font-display text-[11px] font-extrabold uppercase tracking-widest text-white" style={{ textShadow: "0 1px 6px rgba(0,0,0,0.75)" }}>
                        {c.name}
                      </span>
                      <span className="absolute bottom-1.5 right-2.5 text-[9px] font-extrabold uppercase tracking-widest text-white/70">
                        Crew banner
                      </span>
                    </span>
                  )}
                  <span className="flex items-center gap-2.5 sm:gap-3">
                    {/* Big rank number in its medal tile (owner's
                        model): 1 gold, 2 silver, 3 bronze, every
                        other rank on a plain dark tile. */}
                    <span className="font-display flex h-11 w-11 flex-none items-center justify-center rounded-xl text-[19px]" style={rankBadgeStyle(c.rank)} aria-hidden="true">{c.rank}</span>
                    {/* Trend against last season's finish (owner's
                        model): "=" when the crew holds its place,
                        an arrow with the places moved when it
                        climbs or drops, New when it has no finish
                        recorded yet. */}
                    <span className="flex w-[26px] flex-none flex-col items-center leading-none" aria-hidden="true">
                      {c.trend === "up" && (
                        <>
                          <span className="text-[13px] font-extrabold" style={{ color: "var(--accent2)" }}>▲</span>
                          <span className="mt-0.5 text-[11px] font-extrabold" style={{ color: "var(--accent2)" }}>{delta}</span>
                        </>
                      )}
                      {c.trend === "down" && (
                        <>
                          <span className="text-[13px] font-extrabold" style={{ color: "var(--accent)" }}>▼</span>
                          <span className="mt-0.5 text-[11px] font-extrabold" style={{ color: "var(--accent)" }}>{delta}</span>
                        </>
                      )}
                      {c.trend === "same" && <span className="text-[16px] font-extrabold text-[var(--dim)]">=</span>}
                      {c.trend === "new" && <span className="rounded-full px-1.5 py-0.5 text-[9.5px] font-extrabold uppercase tracking-wide" style={{ background: "rgba(0,229,204,0.16)", color: "var(--accent2)" }}>New</span>}
                    </span>
                    <ClanEmblem tag={c.tag} color={c.color} emblem={c.emblem} effect={c.emblemEffect} finish={c.colorFinish} size={c.rank <= 3 ? 48 : 42} />
                    <span className="min-w-0 flex-1">
                      <span className="block truncate font-bold" style={c.rank <= 3 ? { fontSize: 17 } : undefined}>
                        <span className="text-[12px] font-semibold text-[var(--dim)]">[{c.tag}]</span> {c.name}
                      </span>
                      <span className="block truncate text-xs text-[var(--dim)]">
                        {c.league} · x{c.multiplier.toFixed(2)}
                        {board === "global" && c.region ? ` · ${c.region}` : ""}
                        {board === "playstation" || board === "xbox" ? ` · ${c.platform}` : ""}
                      </span>
                    </span>
                    {/* Right side (owner's model): Members count in
                        its own pill, season points big underneath. */}
                    <span className="flex flex-none flex-col items-end gap-1.5">
                      <span className="text-right">
                        <span className="block text-[9.5px] font-extrabold uppercase tracking-widest text-[var(--dim)]">Members</span>
                        <span className="mt-0.5 inline-block rounded-md px-2 py-0.5 text-[12.5px] font-extrabold" style={{ background: "var(--surface)", border: "1px solid var(--border)" }}>{c.memberCount} · Unlimited</span>
                      </span>
                      <span className="text-right">
                        <span className="block text-[16px] font-extrabold leading-none">{c.effectiveSeasonPoints.toLocaleString()}</span>
                        <span className="mt-0.5 block text-[9.5px] font-bold uppercase tracking-widest text-[var(--dim)]">season pts</span>
                      </span>
                    </span>
                  </span>
                </button>
              </li>
            );
          })}
        </ol>
        {!boardQuery && top1000.length > shown && (
          <button
            type="button"
            className="btn-ghost mt-3 w-full"
            onClick={() => setShown((s) => s + 100)}
            aria-label={`Show more crews — showing ${visible.length} of the Top ${top1000.length}`}
          >
            Show more crews — {visible.length} of Top {top1000.length} shown
          </button>
        )}
        </>
        )}
        </div>
      </div>
      {data && !activeLocked && data.graphs[board].crews.length > 1 && (
        <div className="card mt-4 p-4">
          <p className="mb-1 text-[11px] font-extrabold uppercase tracking-widest text-[var(--dim)]">Season points over time — top 5</p>
          <SeasonLines graph={data.graphs[board]} />
        </div>
      )}
    </div>
  );
}

function CommunityEventsPromo({ playerKey, go }: { playerKey: string; go: (t: Tab) => void }) {
  const hosting = useQuery({
    queryKey: ["eventHosting", playerKey],
    queryFn: () => api.getMyEventHosting({ playerKey }),
  });
  const items = hosting.data?.items ?? [];
  const eligible = items.filter((i) => i.eligible);
  const leaderSmall = items.filter((i) => i.isLeader && !i.eligible);
  return (
    <section className="card mt-6 overflow-hidden" aria-label="Community Events — hosted by crew Leaders">
      <div className="relative">
        <img decoding="async" src={eventsPromoUrl} alt="Original ViceSunshine illustration of a community car meet at dusk in a beachfront parking lot, rows of colourful muscle cars under string lights and palms — used only for this Community Events promo" className="h-[150px] w-full object-cover sm:h-[180px]" loading="lazy" />
        <div className="absolute inset-0 bg-[rgba(11,11,20,0.55)]" />
        <div className="absolute inset-x-0 bottom-0 p-5">
          <h3 className="text-xl font-extrabold tracking-tight">Community Events</h3>
          <p className="mt-1 max-w-[520px] text-sm leading-relaxed text-[#e6e3ef]">Car meets, races, time trials, screenshot contests and crew nights — created by crew Leaders, open for everyone to find by name or hashtag.</p>
        </div>
      </div>
      <div className="p-5">
        <p className="text-sm leading-relaxed text-[var(--dim)]">
          Hosting is simple: if you lead a crew with at least 10 members, you can create Public events (anyone can see and join them) or Private events (invite-only — hidden from the list, joined with your invite link or invite code, or by your crew). Players find events by searching the name, or a hashtag like #carmeet, #race or #timetrial.
        </p>
        {hosting.isPending && <p className="mt-3 text-sm text-[var(--dim)]">Checking your crews…</p>}
        {eligible.map((c) => (
          <div key={c.clanId} className="mt-3 flex flex-wrap items-center gap-2 rounded-xl border border-[var(--accent2)] p-3">
            <span className="text-sm font-bold">{c.clanName}</span>
            <span className="text-xs text-[var(--dim)]">{c.memberCount} members · you are the Leader</span>
            <span className="ml-auto text-sm font-bold text-[var(--accent2)]">Your crew can host events</span>
          </div>
        ))}
        {leaderSmall.map((c) => (
          <div key={c.clanId} className="mt-3 flex flex-wrap items-center gap-2 rounded-xl border border-[var(--border)] p-3">
            <span className="text-sm font-bold">{c.clanName}</span>
            <span className="text-xs text-[var(--dim)]">{c.memberCount} of 10 members needed to host — recruit {10 - c.memberCount} more and you can start creating events.</span>
          </div>
        ))}
        {hosting.data && items.length > 0 && eligible.length === 0 && leaderSmall.length === 0 && (
          <p className="mt-3 text-sm text-[var(--dim)]">You are not a crew Leader, so you cannot create events — but you can join every public one. Ask your Leader to host, or found your own crew and grow it to 10 members.</p>
        )}
        {hosting.data && items.length === 0 && (
          <p className="mt-3 text-sm text-[var(--dim)]">You are not in a crew yet — you can still join every public event. Found a crew, grow it to 10 members, and you can host your own.</p>
        )}
        <button type="button" className="btn-primary mt-4" onClick={() => go("events")} aria-label="Open Community Events — browse, search and create events">
          {eligible.length > 0 ? "Browse events & create yours" : "Browse Community Events"}
        </button>
      </div>
    </section>
  );
}

function ClansView({
  playerKey,
  gamertag,
  premium,
  go,
  savedStore,
  onBack,
}: {
  playerKey: string;
  gamertag: string;
  premium: boolean;
  go: (t: Tab) => void;
  savedStore?: ReturnType<typeof useSaved>;
  onBack?: () => void;
}) {
  const qc = useQueryClient();
  // A crew picked on the Crew Leaderboard page hands its id over
  // through this device key (the same pattern as "vv-dm-open"):
  // arriving here with the key set opens that crew's home directly.
  const [openClanId, setOpenClanId] = useState<number | null>(() => {
    try {
      const v = window.localStorage.getItem("vv-open-crew");
      if (v) {
        window.localStorage.removeItem("vv-open-crew");
        const n = Number(v);
        return Number.isFinite(n) && n > 0 ? n : null;
      }
    } catch { /* storage unavailable */ }
    return null;
  });
  // Opening a clan home (or going back to the clan list) starts at
  // the top of the page, never where the list was scrolled to.
  useEffect(() => { scrollPageToTopSoon(); }, [openClanId]);
  const [playstyle, setPlaystyle] = useState("All");
  const [search, setSearch] = useState("");
  const [showCreate, setShowCreate] = useState(false);
  const [error, setError] = useState("");
  // Crew tab categories (owner's direction): once you are in a
  // crew, the Crews tab's main page IS your crew's profile; the
  // directory becomes the Discover category. Before joining, the
  // directory leads with suggestions and creating your own crew.
  const [showMine, setShowMine] = useState<boolean | null>(null);
  const myClan = useQuery({
    queryKey: ["my-clan", playerKey],
    queryFn: () => api.getMyClan({ playerKey }),
    enabled: Boolean(gamertag),
  });
  const crewPulse = useQuery({
    queryKey: ["crew-activity-feed"],
    queryFn: () => api.listCrewActivityFeed({}),
    refetchInterval: 30000,
  });
  const clans = useQuery({
    queryKey: ["clans", playstyle, search],
    queryFn: () => api.listClans({ platform: "All", playstyle, search }),
  });
  const [joinNotice, setJoinNotice] = useState("");
  const join = useMutation({
    mutationFn: async (clan: ClanSummary) =>
      await api.joinClan({
        clanId: clan.id,
        playerKey,
        gamertag,
        platform: "PS5",
        message: "",
      }),
    onSuccess: (res, clan) => {
      setError("");
      qc.invalidateQueries({ queryKey: ["clans"] });
      qc.invalidateQueries({ queryKey: ["clanRankings"] });
      qc.invalidateQueries({ queryKey: ["my-clan"] });
      if (res.joined) {
        setJoinNotice("");
        setOpenClanId(clan.id);
      } else if (res.requested) {
        // The anti-spam gate closed on this one: the tap sent a
        // join request into the crew's chat for its Leader.
        setJoinNotice(
          res.requestReason === "returning"
            ? `Request sent to ${clan.name} — you were in that crew before, so there's no direct way back in. The Leader can accept your request in the crew chat.`
            : `Request sent to ${clan.name} — you already joined a crew this week (one direct join a week). The Leader can accept your request in the crew chat.`,
        );
      } else if (res.applied) {
        setJoinNotice(`Application sent to ${clan.name} — a Leader or Co-Leader will review it.`);
      }
    },
    onError: (e) => setError(e.message),
  });

  if (openClanId) {
    return (
      <ClanHome
        clanId={openClanId}
        playerKey={playerKey}
        gamertag={gamertag}
        onBack={() => setOpenClanId(null)}
        goPremium={() => go("premium")}
      />
    );
  }

  const myClanId = myClan.data?.clanId ?? 0;
  const mineActive = myClanId > 0 && (showMine ?? true);
  const viewSwitcher = myClanId > 0 ? (
    <div className="mb-4 flex flex-wrap gap-2" role="tablist" aria-label="Crews views">
      <button type="button" role="tab" aria-selected={mineActive} className={mineActive ? "btn-game" : "btn-ghost"} onClick={() => setShowMine(true)} aria-label={`My crew — ${myClan.data?.clanName ?? "your crew"}`}>
        My crew{myClan.data?.clanName ? ` · ${myClan.data.clanName}` : ""}
      </button>
      <button type="button" role="tab" aria-selected={!mineActive} className={!mineActive ? "btn-game" : "btn-ghost"} onClick={() => setShowMine(false)} aria-label="Discover crews — popular, trending and recruiting crews">
        Discover crews
      </button>
    </div>
  ) : null;
  if (mineActive) {
    return (
      <div>
        {viewSwitcher}
        <ClanHome clanId={myClanId} playerKey={playerKey} gamertag={gamertag} onBack={() => setShowMine(false)} goPremium={() => go("premium")} />
      </div>
    );
  }

  const items = clans.data?.items ?? [];
  const totalMembers = items.reduce((s, c) => s + c.memberCount, 0);

  return (
    <div className="clans-view">
      {onBack && (
        <button type="button" className="btn-ghost btn-compact mb-3" onClick={onBack} aria-label="Back to where you were">← Back</button>
      )}
      {viewSwitcher}
      <section className="relative overflow-hidden rounded-2xl border border-[var(--border)]">
        <img decoding="async" src={clanArenaUrl} alt="Painted illustration of a neon Vice City crew arena with trophy towers and palm trees — original fan artwork" className="h-[190px] w-full object-cover sm:h-[300px]" loading="lazy" />
        <div className="absolute inset-0 bg-[rgba(11,11,20,0.45)]" />
        <div className="absolute inset-x-0 bottom-0 p-4 sm:p-5">
          <h2 className="text-[24px] font-extrabold leading-tight tracking-tight sm:text-[30px]">Crews</h2>
          <p className="mt-1 max-w-[480px] text-[13px] leading-relaxed text-[#e6e3ef] sm:text-[15px]">Found your own crew and lead it — or find one that fits how you play. Clear roles, honest stats, unlimited members.</p>
          <div className="mt-3 flex flex-wrap gap-2">
            <span className="trophy-pill">{items.length} crews</span>
            <span className="trophy-pill">{totalMembers} members</span>
            <span className="trophy-pill">{items.filter((c) => c.privacy === "Public").length} crews recruiting now</span>
          </div>
        </div>
      </section>

      {!gamertag && (
        <p className="mt-4 rounded-lg border border-[var(--amber)] p-3 text-sm text-[var(--amber)]">
           Set your gamertag first so crews know who is joining.{" "}
          <button type="button" className="font-bold underline" onClick={() => go("profile")}>
            Set up your profile →
          </button>
        </p>
      )}

      {/* Found your own crew — FIRST, above every suggestion
          (owner's direction, Nov 22 2026): most players here want
          to create a clan, not join one, so creating leads the
          page, in full Vice City neon. The old "Highest-ranked
          crew" card that sat here is gone with the rank system.
          The founder form opens directly under this panel. */}
      <section
        className="relative mt-4 overflow-hidden rounded-2xl border p-5 sm:p-6"
        style={{
          borderColor: "var(--accent)",
          background: "linear-gradient(120deg, rgba(255,46,136,0.18), rgba(124,58,237,0.15) 55%, rgba(25,227,194,0.12)), var(--surface)",
        }}
        aria-label="Found your own crew"
      >
        <p className="text-[11px] font-extrabold uppercase tracking-[0.22em] text-[var(--accent2)]">Your crew · Your rules</p>
        <h3 className="font-display mt-1.5 text-[26px] uppercase leading-tight sm:text-3xl">Found your own crew</h3>
        <p className="mt-2 max-w-[540px] text-sm leading-relaxed text-[var(--dim)]">
          Most players on ViceSunshine lead their own crew. Name it, pick your emblem and colour, and your crew chat opens the moment it&apos;s founded — unlimited members, and you start as Leader. Leaders with Premium can found with the gold Vice Crest, Eclipse and Royal Palm emblems, a custom colour and chrome finishes.
        </p>
        <div className="mt-4 flex flex-wrap items-center gap-3">
          <button type="button" className="btn-game" style={{ minHeight: 50, padding: "10px 22px", fontSize: 16 }} onClick={() => setShowCreate(!showCreate)} aria-expanded={showCreate} aria-label={showCreate ? "Close the crew founder form" : "Create a crew — open the founder form"}>
            {showCreate ? "Close the founder" : " Create a crew"}
          </button>
          <span className="text-[13px] font-semibold text-[var(--dim)]">Founding costs 500 Vice Credits — every new account starts with exactly 500.</span>
        </div>
      </section>
      {showCreate && (
        <div className="mt-4">
          <CreateClanForm
            playerKey={playerKey}
            gamertag={gamertag}
            premium={premium}
            onCreated={(id) => { setShowCreate(false); setOpenClanId(id); }}
            goProfile={() => go("profile")}
          />
        </div>
      )}

      {crewPulse.data && crewPulse.data.items.length > 0 && (
        <section className="card mt-4 p-4" aria-label="Live crew activity">
          <h3 className="flex items-center gap-2 text-[15px] font-extrabold tracking-tight">
            <span className="inline-block h-2 w-2 animate-pulse rounded-full bg-[var(--accent2)]" aria-hidden="true" />
            Live in crews right now
          </h3>
          <ul className="mt-2.5 grid gap-2">
            {crewPulse.data.items.slice(0, 6).map((a) => (
              <li key={a.id} className="flex items-center gap-2.5 text-[13.5px]">
                <span className="flex-none"><ClanEmblem tag={a.clanTag} color={a.clanColor} emblem={a.clanEmblem} effect={a.clanEmblemEffect} finish={a.clanColorFinish} size={26} /></span>
                <span className="min-w-0 flex-1 truncate"><strong>{a.clanName}</strong> — {a.text}</span>
                <span className="flex-none text-[12px] text-[var(--dim)]">{a.at ? timeAgo(a.at) : ""}</span>
              </li>
            ))}
          </ul>
        </section>
      )}

      {/* Browse crews — one aligned directory: a section header,
          an even playstyle filter grid (6 tiles: 3 × 2 on phone,
          one row of 6 on desktop), a full-width search in line
          with the grid below, then the crew cards. The separate
          "Suggested for you" / "Trending crews" block that used
          to sit here is gone (owner's direction, Nov 22 2026 —
          fewer suggestions; creating leads the page instead),
          and creating lives at the top of the page now, not in
          a button buried beside the filters. */}
      <h3 className="font-display mt-8 text-xl leading-tight">Browse crews</h3>
      <p className="mt-0.5 text-sm text-[var(--dim)]">Every crew in Leonida — open one to see its page, or join straight from its card and land in its crew chat.</p>
      <div className="mt-4 grid grid-cols-3 gap-2 sm:grid-cols-6" role="group" aria-label="Filter by playstyle">
        {["All", ...PLAYSTYLES].map((p) => (
          <button key={p} type="button" className="picker-tile" aria-pressed={playstyle === p} onClick={() => setPlaystyle(p)} aria-label={`Playstyle: ${p}`}>
            {p}
          </button>
        ))}
      </div>
      <label htmlFor="clan-search" className="sr-only">Search crews by name or tag</label>
      <input
        id="clan-search"
        className="field mt-3"
        {...FIELDS.listClans.search}
        placeholder=" Search crews by name or tag…"
        value={search}
        onChange={(e) => setSearch(e.target.value)}
      />
      {error && <p className="mt-3 text-sm text-[var(--amber)]" role="alert">{error}</p>}
      {joinNotice && <p className="mt-3 text-sm font-semibold text-[var(--accent2)]" role="status">{joinNotice}</p>}

      {clans.isPending && <p className="mt-4 text-sm text-[var(--dim)]">Loading crews...</p>}
      {clans.data && items.length === 0 && (
        <div className="card mt-4 p-6 text-center">
          <p className="text-4xl" aria-hidden="true"></p>
          <p className="mt-2 font-bold">No crews here yet.</p>
          <p className="mt-1 text-sm text-[var(--dim)]">Found the first crew and you become its Leader — crews hold unlimited members.</p>
        </div>
      )}
      <div className="mt-5 grid gap-5 sm:grid-cols-2">
        {items.map((c: ClanSummary) => (
          <ClanCard
            key={c.id}
            c={c}
            onOpen={() => setOpenClanId(c.id)}
            onJoin={() => join.mutate(c)}
            joinDisabled={!gamertag}
            joinPending={join.isPending}
            savedStore={savedStore}
          />
        ))}
      </div>

      <CommunityEventsPromo playerKey={playerKey} go={go} />

      {/* The XP / points-earning panel is on hold
          (SHOW_POINTS_EARNING above) — hidden, not deleted. */}
      {SHOW_POINTS_EARNING && <HowToEarnPanel />}

      {/* The Crew perks section is off for now
          (SHOW_CREW_PERKS above) — hidden, not deleted. */}
      {SHOW_CREW_PERKS && <ClanPerksPanel />}

      {/* Nothing else follows the directory (owner's direction,
          Nov 22 2026): the Crew Leaderboard entry card and the
          Rank ladder section that used to close this page are
          REMOVED — there is no ranking system in ViceSunshine.
          Crew roles (Leader, Co-Leader, Elder, Member, Recruit)
          still exist inside each crew for managing members;
          they are simply not displayed as a ladder here. */}
    </div>
  );
}

function CreateClanForm({
  playerKey,
  gamertag,
  premium,
  onCreated,
  goProfile,
}: {
  playerKey: string;
  gamertag: string;
  premium: boolean;
  onCreated: (id: number) => void;
  goProfile: () => void;
}) {
  const qc = useQueryClient();
  const wallet = useQuery({ queryKey: ["wallet", playerKey], queryFn: () => api.getWallet({ playerKey }) });
  const balance = wallet.data?.hasProfile ? wallet.data.balance : null;
  const clanCost = wallet.data?.clanCreateCost ?? 500;
  const canAfford = balance !== null && balance >= clanCost;
  const [step, setStep] = useState(1);
  const [name, setName] = useState("");
  const [tag, setTag] = useState("");
  const [color, setColor] = useState("#FF2E88");
  const [emblem, setEmblem] = useState("sunset");
  const [motto, setMotto] = useState("");
  const [description, setDescription] = useState("");
  const [rules, setRules] = useState("");
  const [requirements, setRequirements] = useState("");
  const [clanPlatform, setClanPlatform] = useState<"PS5" | "Xbox" | "Both">("Both");
  const [region, setRegion] = useState("");
  const [language, setLanguage] = useState("English");
  const [playstyle, setPlaystyle] = useState("Chill");
  const [privacy, setPrivacy] = useState<"Public" | "Invite-Only" | "Application">("Public");
  const [moreOpen, setMoreOpen] = useState(false);
  const [error, setError] = useState("");
  const create = useMutation({
    mutationFn: async () =>
      await api.createClan({
        playerKey, gamertag,
        name: name.trim(), tag: tag.trim(), color, emblem: emblem as "sunset" | "crown" | "serpent" | "diamond" | "wave" | "vicecrest" | "eclipse" | "royal-palm", motto, description, rules, requirements,
        clanPlatform, region, language, playstyle, privacy,
      }),
    onSuccess: (res) => {
      qc.invalidateQueries({ queryKey: ["clans"] });
      qc.invalidateQueries({ queryKey: ["clanRankings"] });
      qc.invalidateQueries({ queryKey: ["wallet"] });
      qc.invalidateQueries({ queryKey: ["profile"] });
      qc.invalidateQueries({ queryKey: ["dm-conversations"] });
      onCreated(res.id);
    },
    onError: (e) => setError(e.message),
  });

  // Live name / tag availability — checked while typing (debounced),
  // so a taken name or tag is refused here, in plain words, long
  // before the Found button.
  const [debName, setDebName] = useState("");
  const [debTag, setDebTag] = useState("");
  useEffect(() => {
    const t = setTimeout(() => { setDebName(name.trim()); setDebTag(tag.trim().toUpperCase()); }, 350);
    return () => clearTimeout(t);
  }, [name, tag]);
  const avail = useQuery({
    queryKey: ["crew-availability", debName, debTag],
    queryFn: () => api.checkCrewAvailability({ name: debName, tag: debTag }),
    enabled: debName.length >= 3 || debTag.length >= 2,
  });
  const nameChecked = debName === name.trim() && name.trim().length >= 3 && avail.data !== undefined;
  const tagChecked = debTag === tag.trim().toUpperCase() && tag.trim().length >= 2 && avail.data !== undefined;
  const nameTaken = nameChecked && (avail.data?.nameTaken ?? false);
  const tagFormatOk = /^[A-Z0-9]{2,4}$/.test(tag.trim().toUpperCase());
  const tagTaken = tagChecked && tagFormatOk && (avail.data?.tagTaken ?? false);
  const nameOk = name.trim().length >= 3 && !nameTaken;
  const tagOk = tagFormatOk && !tagTaken;
  const step1Ok = nameOk && tagOk;

  if (!gamertag) {
    return (
      <div className="card p-4 text-sm">
        You need a gamertag before founding a crew.{" "}
        <button type="button" className="font-bold underline" onClick={goProfile}>Set it up →</button>
      </div>
    );
  }

  const preview: ClanSummary = {
    id: 0, name: name.trim() || "Your Crew", tag: tag.trim().toUpperCase() || "NVDA", color, colorFinish: "", emblem, emblemEffect: "",
    motto, description, rules, requirements, badge: "", themeAccent: "", platform: clanPlatform, region, language, playstyle, privacy,
    maxMembers: 0, memberCount: 1, eventsHeld: 0, wins: 0,
    faction: "", factionPoints: 0, trophies: 0, league: "Ocean Drive",
    walletCredits: 0, bannerStyle: "", callingCard: "", headerImageUrl: "", nameColor: "", rankPoints: 0, seasonPoints: 0,
    effectiveSeasonPoints: 0, effectiveLifetimePoints: 0, multiplier: 1, avgMemberLevel: 1, warsWon: 0, seasonRank: 0,
  };

  const steps = ["Identity", "Details", "Review"] as const;
  const availMsg = (ok: boolean, taken: boolean, okText: string, takenText: string) =>
    taken ? (
      <p className="mt-1.5 text-sm font-semibold text-[#ff6b81]" role="alert">{takenText}</p>
    ) : ok ? (
      <p className="mt-1.5 text-sm font-semibold text-[var(--accent2)]" role="status">{okText}</p>
    ) : null;

  return (
    <form
      className="card p-5 sm:p-6"
      onSubmit={(e) => {
        e.preventDefault();
        setError("");
        if (step === 1) { if (step1Ok) setStep(2); return; }
        if (step === 2) { setStep(3); return; }
        if (!step1Ok) { setStep(1); setError("Check your crew name and tag on step 1 — one of them is not available."); return; }
        if (balance === null || !canAfford) { setError(`Founding a crew costs ${clanCost} Vice Credits — your balance is ${balance ?? 0}.`); return; }
        create.mutate();
      }}
    >
      <p className="text-[11px] font-extrabold uppercase tracking-[0.22em] text-[var(--accent2)]">Crew founder</p>
      <h3 className="font-display mt-1 text-2xl uppercase leading-tight sm:text-[28px]"> Found your crew</h3>
      <p className="mt-1.5 max-w-[520px] text-sm leading-relaxed text-[var(--dim)]">Three quick steps — name it, style it, launch it. Your crew chat opens the moment it&apos;s founded. Premium Leaders can found with the Premium emblems, a custom colour and chrome finishes.</p>
      <div className="mt-4 h-[3px] rounded-full" style={{ background: "linear-gradient(90deg, var(--accent), var(--accent2), transparent)" }} aria-hidden="true" />

      {/* Step indicator: 1 Identity → 2 Details → 3 Review */}
      <ol className="mt-4 flex items-center gap-1.5" aria-label="Create a crew — steps">
        {steps.map((label, i) => {
          const n = i + 1;
          const state = n === step ? "current" : n < step ? "done" : "todo";
          return (
            <li key={label} className="flex min-w-0 flex-1 items-center gap-1.5">
              <button
                type="button"
                disabled={n >= step}
                onClick={() => { if (n < step) setStep(n); }}
                aria-current={state === "current" ? "step" : undefined}
                aria-label={`Step ${n}: ${label}${state === "current" ? " (current)" : state === "done" ? " (done — go back)" : ""}`}
                className="flex min-w-0 items-center gap-2 rounded-full px-2 py-1.5 text-left"
                style={{
                  background: state === "current" ? "var(--accent)" : "var(--surface2)",
                  color: state === "current" ? "#fff" : "var(--dim)",
                  border: "1px solid var(--border)",
                }}
              >
                <span className="flex h-6 w-6 flex-none items-center justify-center rounded-full text-[12px] font-extrabold" style={{ background: state === "current" ? "rgba(255,255,255,0.25)" : "var(--surface3)" }} aria-hidden="true">{state === "done" ? "✓" : n}</span>
                <span className="truncate text-[13px] font-extrabold">{label}</span>
              </button>
              {n < 3 && <span className="flex-none text-[var(--dim)]" aria-hidden="true">→</span>}
            </li>
          );
        })}
      </ol>

      <div className="mt-5 grid items-start gap-6 lg:grid-cols-[minmax(0,1fr)_360px]">
        {/* Live preview — top on mobile, right side on desktop,
            always visible and updating as you type. */}
        <div className="order-1 lg:order-2 lg:sticky lg:top-4">
          <div className="pointer-events-none mx-auto max-w-sm lg:max-w-none" aria-hidden="true">
            <ClanCard c={preview} onOpen={() => {}} onJoin={() => {}} joinDisabled joinPending={false} />
          </div>
          <p className="mt-2 text-center text-xs text-[var(--dim)]">Live preview — this is your crew card, updating as you type.</p>
        </div>

        <div className="order-2 min-w-0 lg:order-1">
          {step === 1 && (
            <div>
              <div>
                <label className="flabel" htmlFor="clan-name">Crew name</label>
                <input id="clan-name" className="field" {...FIELDS.createClan.name} value={name} onChange={(e) => setName(e.target.value)} placeholder="Neon Kings" aria-describedby="clan-name-note clan-name-avail" />
                <p id="clan-name-note" className="mt-1.5 rounded-lg px-2.5 py-1.5 text-[13px] font-semibold leading-relaxed" style={{ border: "1px solid var(--amber)", color: "var(--amber)" }}>
                  Choose carefully — your crew name is permanent and can&apos;t be changed later.
                </p>
                <div id="clan-name-avail">
                  {name.trim().length > 0 && name.trim().length < 3 && (
                    <p className="mt-1.5 text-sm text-[var(--dim)]">Crew names need at least 3 characters.</p>
                  )}
                  {availMsg(nameChecked && !nameTaken, nameTaken, `✓ “${name.trim()}” is available.`, "That crew name is already taken — pick another one.")}
                </div>
              </div>
              <div className="mt-4">
                <label className="flabel" htmlFor="clan-tag">Crew tag (2–4 characters)</label>
                <input
                  id="clan-tag"
                  className="field"
                  {...FIELDS.createClan.tag}
                  value={tag}
                  onChange={(e) => setTag(e.target.value.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 4))}
                  placeholder="NVDA"
                  autoComplete="off"
                  aria-describedby="clan-tag-avail"
                />
                <div id="clan-tag-avail">
                  {tag.trim().length > 0 && !tagFormatOk && (
                    <p className="mt-1.5 text-sm font-semibold text-[#ff6b81]" role="alert">Tags are 2–4 characters — letters and numbers only.</p>
                  )}
                  {availMsg(tagChecked && tagFormatOk && !tagTaken, tagTaken, `✓ Tag [${tag.trim().toUpperCase()}] is available.`, `Tag [${tag.trim().toUpperCase()}] is already taken by another crew — no two crews can share a tag. Try another.`)}
                </div>
                <p className="mt-1.5 text-[13px] leading-relaxed text-[var(--dim)]">
                  Your tag shows in front of every member&apos;s name while they are in the crew — like <strong style={{ color }}>[{tag.trim().toUpperCase() || "NVDA"}]</strong> <strong className="text-[var(--text)]">{gamertag}</strong> — and it disappears the moment they leave.
                </p>
              </div>

              <span className="flabel" id="emblem-label">Pick your emblem</span>
              <p className="mb-2 text-[13px] leading-relaxed text-[var(--dim)]">The Crew Emblems catalogue — the same emblems as Crew Settings → Crew customisation. Premium emblems need your Premium.</p>
              <div className="grid grid-cols-4 gap-2" role="group" aria-labelledby="emblem-label">
                {CREW_CATALOGUE_EMBLEMS.map((e) => {
                  const lockedPremium = !!e.premiumOnly && !premium;
                  return (
                    <button key={e.value} type="button" className="picker-tile" aria-pressed={emblem === e.value} disabled={lockedPremium} onClick={() => setEmblem(e.value)} aria-label={lockedPremium ? `Emblem: ${e.name} — included with Premium` : `Emblem: ${e.name}${e.premiumOnly ? " — Premium" : ""}`}>
                      <span className="flex justify-center" aria-hidden="true"><ClanEmblem tag={tag.trim().toUpperCase() || "NV"} color={color} size={40} emblem={e.value} /></span>
                      {e.name}{e.premiumOnly ? <span className="font-semibold text-[var(--dim)]">Premium</span> : null}
                    </button>
                  );
                })}
              </div>
              {!premium && <p className="mt-1.5 text-[13px] leading-relaxed text-[var(--dim)]">Premium members can also found their crew with the gold Vice Crest, Eclipse or Royal Palm emblem.</p>}

              <span className="flabel" id="color-label">Crew colour</span>
              <p className="mb-2 text-[13px] leading-relaxed text-[var(--dim)]">The Crew Colours catalogue — the same colours as Crew Settings → Crew customisation. This colour is your crew's colour: it colours the Crew tag in front of every member's name and the crew emblem. Every named colour is free; the custom colour tool below is part of Premium.</p>
              <div className="flex flex-wrap items-center gap-2" role="group" aria-labelledby="color-label">
                {CREW_CATALOGUE_COLORS.map((col) => (
                  <button key={col.value} type="button" className="swatch" style={{ background: col.value }} aria-pressed={color.toLowerCase() === col.value.toLowerCase()} onClick={() => setColor(col.value)} aria-label={`Crew colour ${col.name}`} />
                ))}
              </div>
              <p className="mt-3 text-[13px] font-bold">Or a custom colour — any colour you like {premium ? "" : "— Premium"}:</p>
              <div className="mt-1.5">
                <CustomColorControl id="clan-custom-color" value={color} onChange={setColor} fieldProps={FIELDS.createClan.color} disabled={!premium} />
              </div>
              {premium ? (
                <p className="mt-1.5 text-[13px] leading-relaxed text-[var(--dim)]">Your Premium is on — the custom colour applies to your emblem, your members&apos; tags and your crew card the moment the crew is founded. Chrome, Gold Chrome, Rose Gold and Iridescent finishes live in Crew Settings → Crew customisation once your crew exists.</p>
              ) : (
                <p className="mt-1.5 text-[13px] leading-relaxed text-[var(--dim)]">Custom colours are included with Premium — pick any named colour above for free, or go Premium to found your crew with a custom colour and finishes like Chrome.</p>
              )}
            </div>
          )}

          {step === 2 && (
            <div>
              <span className="flabel" id="style-label">Playstyle</span>
              <div className="grid grid-cols-3 gap-2 sm:grid-cols-5" role="group" aria-labelledby="style-label">
                {PLAYSTYLES.map((p) => (
                  <button key={p} type="button" className="picker-tile" aria-pressed={playstyle === p} onClick={() => setPlaystyle(p)} aria-label={`Playstyle: ${p}`}>
                    {p}
                  </button>
                ))}
              </div>

              <span className="flabel" id="privacy-label">Who can join?</span>
              <div className="grid grid-cols-3 gap-2" role="group" aria-labelledby="privacy-label">
                {([
                  ["Public", "", "Anyone joins"],
                  ["Application", "", "Apply first"],
                  ["Invite-Only", "", "Invite only"],
                ] as const).map(([p, icon, sub]) => (
                  <button key={p} type="button" className="picker-tile" aria-pressed={privacy === p} onClick={() => setPrivacy(p)} aria-label={`Who can join: ${p} — ${sub}`}>
                    <span className="text-2xl" aria-hidden="true">{icon}</span>{p}<span className="font-semibold text-[var(--dim)]">{sub}</span>
                  </button>
                ))}
              </div>

              <span className="flabel" id="cplatform-label">Platform</span>
              <div className="grid grid-cols-3 gap-2" role="group" aria-labelledby="cplatform-label">
                {([
                  ["PS5", "", "PlayStation"],
                  ["Xbox", "", "Xbox"],
                  ["Both", "", "Everyone"],
                ] as const).map(([p, icon, sub]) => (
                  <button key={p} type="button" className="picker-tile" aria-pressed={clanPlatform === p} onClick={() => setClanPlatform(p)} aria-label={`Platform: ${p}`}>
                    <span className="text-2xl" aria-hidden="true">{icon}</span>{p}<span className="font-semibold text-[var(--dim)]">{sub}</span>
                  </button>
                ))}
              </div>

              <label className="flabel" htmlFor="clan-desc">Bio — your crew's description</label>
              <textarea id="clan-desc" className="field" rows={3} {...FIELDS.createClan.description} value={description} onChange={(e) => setDescription(e.target.value)} placeholder="What is this crew about?" />
              <p className="mt-1.5 text-[13px] leading-relaxed text-[var(--dim)]">Shows in the Bio section on your crew's page. You and your Co-Leaders can edit it later in Crew Settings → Bio &amp; Rules.</p>

              <label className="flabel" htmlFor="clan-rules">Crew rules</label>
              <textarea id="clan-rules" className="field" rows={4} {...FIELDS.createClan.rules} value={rules} onChange={(e) => setRules(e.target.value)} placeholder={"One rule per line, e.g.\nNo team-killing\nBe on for crew nights"} aria-describedby="clan-rules-hint" />
              <p id="clan-rules-hint" className="mt-1.5 text-[13px] leading-relaxed text-[var(--dim)]">One rule per line. They show on your crew&apos;s page, and everyone who joins agrees to them. You and your Co-Leaders can edit them later.</p>

              <label className="flabel" htmlFor="clan-req">Requirements to join</label>
              <textarea id="clan-req" className="field" rows={3} {...FIELDS.createClan.requirements} value={requirements} onChange={(e) => setRequirements(e.target.value)} placeholder={"One per line, e.g.\nPS5 only\nMic preferred\nActive most weekends"} aria-describedby="clan-req-hint" />
              <p id="clan-req-hint" className="mt-1.5 text-[13px] leading-relaxed text-[var(--dim)]">One per line — platform, activity, mic, anything a joiner must meet. They show with the rules on your crew's page and in the join flow, where joiners confirm: "By joining you agree to this crew's rules and meet its requirements".</p>

              <button type="button" className="btn-ghost mt-4 w-full" aria-expanded={moreOpen} onClick={() => setMoreOpen((v) => !v)}>
                More details (optional) {moreOpen ? "▾" : "▸"}
              </button>
              {moreOpen && (
                <div className="mt-3 grid gap-0 sm:grid-cols-2 sm:gap-x-4">
                  <div>
                    <label className="flabel" htmlFor="clan-motto">Motto</label>
                    <input id="clan-motto" className="field" {...FIELDS.createClan.motto} value={motto} onChange={(e) => setMotto(e.target.value)} placeholder="Ride the neon" />
                  </div>
                  <div>
                    <label className="flabel" htmlFor="clan-region">Region</label>
                    <RegionPicker id="clan-region" value={region} onChange={setRegion} placeholder="Start typing — Canada, EU, US East…" fieldProps={FIELDS.createClan.region} />
                  </div>
                  <div>
                    <label className="flabel" htmlFor="clan-lang">Language</label>
                    <input id="clan-lang" className="field" {...FIELDS.createClan.language} value={language} onChange={(e) => setLanguage(e.target.value)} />
                  </div>
                </div>
              )}
              <p className="mt-4 text-sm text-[var(--dim)]">Members: <strong className="text-[var(--text)]">Unlimited</strong> — crews have no member cap. You start as Leader.</p>
            </div>
          )}

          {step === 3 && (
            <div>
              <h4 className="text-base font-extrabold">Review your crew</h4>
              <dl className="mt-3 grid gap-2 text-sm">
                <div className="flex justify-between gap-3 rounded-xl border border-[var(--border)] px-3 py-2"><dt className="text-[var(--dim)]">Crew name</dt><dd className="font-bold">{name.trim()} <span className="font-semibold text-[var(--dim)]">(permanent)</span></dd></div>
                <div className="flex justify-between gap-3 rounded-xl border border-[var(--border)] px-3 py-2"><dt className="text-[var(--dim)]">Crew tag</dt><dd className="font-bold" style={{ color }}>[{tag.trim().toUpperCase()}]</dd></div>
                <div className="flex justify-between gap-3 rounded-xl border border-[var(--border)] px-3 py-2"><dt className="text-[var(--dim)]">Playstyle</dt><dd className="font-bold">{playstyle}</dd></div>
                <div className="flex justify-between gap-3 rounded-xl border border-[var(--border)] px-3 py-2"><dt className="text-[var(--dim)]">Who can join</dt><dd className="font-bold">{privacy}</dd></div>
                <div className="flex justify-between gap-3 rounded-xl border border-[var(--border)] px-3 py-2"><dt className="text-[var(--dim)]">Platform</dt><dd className="font-bold">{clanPlatform}</dd></div>
                <div className="flex justify-between gap-3 rounded-xl border border-[var(--border)] px-3 py-2"><dt className="text-[var(--dim)]">Members</dt><dd className="font-bold">Unlimited</dd></div>
                {rules.trim() && (
                  <div className="rounded-xl border border-[var(--border)] px-3 py-2">
                    <dt className="text-[var(--dim)]">Crew rules</dt>
                    <dd className="mt-1 whitespace-pre-line font-semibold leading-relaxed">{rules.trim()}</dd>
                  </div>
                )}
                {requirements.trim() && (
                  <div className="rounded-xl border border-[var(--border)] px-3 py-2">
                    <dt className="text-[var(--dim)]">Requirements to join</dt>
                    <dd className="mt-1 whitespace-pre-line font-semibold leading-relaxed">{requirements.trim()}</dd>
                  </div>
                )}
              </dl>
              <p className="mt-3 text-sm leading-relaxed text-[var(--dim)]">You can customise your crew's badge, banner and theme in Crew Settings after creating.</p>
              <div className="mt-4 rounded-xl border border-[var(--border)] bg-[var(--surface2)] p-4" role="status">
                <p className="text-sm font-bold">Found crew — {clanCost} Vice Credits</p>
                <p className="mt-1 text-sm leading-relaxed text-[var(--dim)]">
                  {balance === null
                    ? "Every new account starts with 500 Vice Credits — exactly enough to found one crew. Create your profile first so your wallet exists."
                    : canAfford
                      ? `Your balance: ${balance} Vice Credits. After founding: ${balance - clanCost} Vice Credits.`
                      : `Your balance: ${balance} Vice Credits — not enough yet. Earn more from confirmed in-app activity and seasonal awards, then come back.`}
                </p>
              </div>
            </div>
          )}

          {error && <p className="mt-3 text-sm font-semibold text-[#ff6b81]" role="alert">{error}</p>}
          <div className="mt-5 flex flex-wrap items-center gap-2">
            {step > 1 && (
              <button type="button" className="btn-ghost" onClick={() => { setError(""); setStep(step - 1); }}>← Back</button>
            )}
            {step < 3 ? (
              <button type="submit" className="btn-game ml-auto" disabled={step === 1 && !step1Ok} aria-label={step === 1 ? "Continue to step 2: Details" : "Continue to step 3: Review"}>
                Continue →
              </button>
            ) : (
              <button type="submit" className="btn-game ml-auto" disabled={create.isPending || balance === null || !canAfford} aria-label={`Found ${name.trim() || "your crew"} — ${clanCost} Vice Credits`}>
                {create.isPending ? "Founding…" : ` Found crew — ${clanCost} Vice Credits`}
              </button>
            )}
          </div>
          {step === 1 && !step1Ok && (name.trim() !== "" || tag.trim() !== "") && (
            <p className="mt-2 text-right text-[13px] text-[var(--dim)]">Pick an available name and tag to continue.</p>
          )}
        </div>
      </div>
    </form>
  );
}

/* Crew card header background editor (Crew Settings → Crew
   customisation, LEADER ONLY — the tab itself only renders for
   the Leader, and the server refuses anyone else). The Leader
   picks a picture, drags to position it and zooms to crop it to
   the header area's shape; the crop is baked at 1200×500 and
   uploaded through uploadCrewHeaderImage (safety-checked before
   storage). A live preview of the real card header updates while
   editing. Removing the picture returns the header to the
   automatic background: the crew's calling card artwork when it
   has one, else a gradient matched to the crew colour. */
const HEADER_CROP_W = 1200;
const HEADER_CROP_H = 500;

function CrewHeaderBackgroundEditor({ clan, playerKey, onChanged }: {
  clan: ClanSummary;
  playerKey: string;
  onChanged: () => void;
}) {
  const [msg, setMsg] = useState("");
  const [err, setErr] = useState("");
  const [img, setImg] = useState<HTMLImageElement | null>(null);
  const [imgSrc, setImgSrc] = useState("");
  const [zoom, setZoom] = useState(1);
  const [pan, setPan] = useState({ x: 0, y: 0 });
  const [previewUrl, setPreviewUrl] = useState("");
  const frameRef = useRef<HTMLDivElement | null>(null);
  const dragRef = useRef<{ px: number; py: number } | null>(null);
  const fileRef = useRef<HTMLInputElement | null>(null);

  const layout = img ? (() => {
    const s0 = Math.max(HEADER_CROP_W / img.naturalWidth, HEADER_CROP_H / img.naturalHeight);
    const s = s0 * zoom;
    const dw = img.naturalWidth * s;
    const dh = img.naturalHeight * s;
    const maxX = Math.max(0, (dw - HEADER_CROP_W) / 2);
    const maxY = Math.max(0, (dh - HEADER_CROP_H) / 2);
    const cx = Math.min(maxX, Math.max(-maxX, pan.x));
    const cy = Math.min(maxY, Math.max(-maxY, pan.y));
    return { dw, dh, dx: (HEADER_CROP_W - dw) / 2 + cx, dy: (HEADER_CROP_H - dh) / 2 + cy, maxX, maxY };
  })() : null;

  // Bake the current crop to a JPEG data URL — it drives the live
  // card-header preview and is exactly what Save uploads.
  useEffect(() => {
    if (!img || !layout) { setPreviewUrl(""); return; }
    const canvas = document.createElement("canvas");
    canvas.width = HEADER_CROP_W;
    canvas.height = HEADER_CROP_H;
    const g = canvas.getContext("2d");
    if (!g) return;
    g.drawImage(img, layout.dx, layout.dy, layout.dw, layout.dh);
    setPreviewUrl(canvas.toDataURL("image/jpeg", 0.85));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [img, zoom, pan]);

  const pick = (f: File | undefined) => {
    setErr("");
    setMsg("");
    if (!f) return;
    if (f.type !== "image/jpeg" && f.type !== "image/png") {
      setErr("Header pictures must be JPG or PNG.");
      return;
    }
    const url = URL.createObjectURL(f);
    const im = new Image();
    im.onload = () => { setImg(im); setImgSrc(url); setZoom(1); setPan({ x: 0, y: 0 }); };
    im.onerror = () => setErr("That picture could not be read — try another one.");
    im.src = url;
  };

  const onPointerDown = (e: ReactPointerEvent<HTMLDivElement>) => {
    dragRef.current = { px: e.clientX, py: e.clientY };
    e.currentTarget.setPointerCapture(e.pointerId);
  };
  const onPointerMove = (e: ReactPointerEvent<HTMLDivElement>) => {
    const d = dragRef.current;
    if (!d || !frameRef.current || !layout) return;
    const scale = HEADER_CROP_W / frameRef.current.clientWidth;
    setPan((p) => ({
      x: Math.min(layout.maxX, Math.max(-layout.maxX, p.x + (e.clientX - d.px) * scale)),
      y: Math.min(layout.maxY, Math.max(-layout.maxY, p.y + (e.clientY - d.py) * scale)),
    }));
    dragRef.current = { px: e.clientX, py: e.clientY };
  };
  const endDrag = () => { dragRef.current = null; };

  const save = useMutation({
    mutationFn: async () => {
      const comma = previewUrl.indexOf(",");
      if (comma < 0) throw new Error("Pick a picture first, then save.");
      return await api.uploadCrewHeaderImage({
        clanId: clan.id, playerKey, filename: "crew-header.jpg",
        mimeType: "image/jpeg", dataBase64: previewUrl.slice(comma + 1),
      });
    },
    onSuccess: () => {
      setMsg("Header picture saved — it is live on your crew card and at the top of your crew page now.");
      setErr("");
      setImg(null);
      setImgSrc("");
      onChanged();
    },
    onError: (e) => setErr(e.message),
  });
  const remove = useMutation({
    mutationFn: async () => await api.removeCrewHeaderImage({ clanId: clan.id, playerKey }),
    onSuccess: () => {
      setMsg("Custom picture removed — your header is back to the automatic background, matched to your crew.");
      setErr("");
      setImg(null);
      setImgSrc("");
      onChanged();
    },
    onError: (e) => setErr(e.message),
  });

  const design = clan.callingCard ? cardDesignOf(clan.callingCard) : undefined;
  const automaticLabel = clan.headerImageUrl
    ? null
    : design
      ? `Automatic right now: your banner artwork — the ${design.title} calling card — is your header background.`
      : "Automatic right now: a gradient matched to your crew colour.";

  return (
    <section className="mt-3 border-b border-[var(--border)] pb-5" aria-label="Crew card header background">
      <h4 className="font-display uppercase">Header background</h4>
      <p className="mt-1.5 max-w-[620px] text-sm leading-relaxed text-[var(--dim)]">
        The picture behind your crew&apos;s emblem, name and motto on the crew card — and at the top of your crew page.
        Upload your own, or leave it automatic: without a custom picture your header matches your crew — your banner
        artwork if your crew has one, otherwise your crew colour. Only you, the Leader, can change this.
      </p>
      {automaticLabel && <p className="mt-2 text-sm font-semibold text-[var(--accent2)]">{automaticLabel}</p>}
      {clan.headerImageUrl && !img && <p className="mt-2 text-sm font-semibold text-[var(--accent2)]">A custom picture is live as your header background.</p>}
      {msg && <p className="mt-2 text-sm font-semibold text-[var(--accent2)]" role="status">{msg}</p>}
      {err && <p className="mt-2 text-sm font-semibold text-[#ff6b81]" role="alert">{err}</p>}

      {!img && (
        <>
          <p className="flabel">Live preview — your crew card header</p>
          <div className="overflow-hidden rounded-xl border border-[var(--border)]">
            <CrewCardHeader c={clan} />
          </div>
          <div className="mt-3 flex flex-wrap gap-2">
            <button type="button" className="btn-game" onClick={() => fileRef.current?.click()} aria-label="Upload a custom header picture for your crew card">
              {clan.headerImageUrl ? "Replace header picture" : "Upload a header picture"}
            </button>
            {clan.headerImageUrl && (
              <button type="button" className="btn-ghost" disabled={remove.isPending} onClick={() => { setMsg(""); setErr(""); remove.mutate(); }} aria-label="Remove the custom header picture and go back to the automatic header">
                Remove — back to automatic
              </button>
            )}
          </div>
        </>
      )}

      {img && layout && (
        <div className="mt-3">
          <p className="flabel">Position your picture — drag to move it, zoom to crop</p>
          <div
            ref={frameRef}
            className="relative w-full touch-none select-none overflow-hidden rounded-xl border border-[var(--border)]"
            style={{ aspectRatio: `${HEADER_CROP_W} / ${HEADER_CROP_H}`, cursor: "grab", background: "var(--surface2)" }}
            onPointerDown={onPointerDown}
            onPointerMove={onPointerMove}
            onPointerUp={endDrag}
            onPointerCancel={endDrag}
            role="img"
            aria-label="Crop frame for your header picture — drag to position the picture inside the header shape"
          >
            <img
              src={imgSrc}
              alt=""
              draggable={false}
              className="absolute max-w-none"
              style={{
                left: `${(layout.dx / HEADER_CROP_W) * 100}%`,
                top: `${(layout.dy / HEADER_CROP_H) * 100}%`,
                width: `${(layout.dw / HEADER_CROP_W) * 100}%`,
                height: `${(layout.dh / HEADER_CROP_H) * 100}%`,
              }}
            />
          </div>
          <label className="flabel" htmlFor="crew-header-zoom">Zoom</label>
          <input
            id="crew-header-zoom"
            type="range"
            min={1}
            max={2.5}
            step={0.01}
            value={zoom}
            onChange={(e) => setZoom(Number(e.target.value))}
            className="w-full max-w-sm"
            aria-label="Zoom the header picture"
          />
          <p className="flabel">Live preview — your crew card header with this picture</p>
          <div className="overflow-hidden rounded-xl border border-[var(--border)]">
            <CrewCardHeader c={{ ...clan, headerImageUrl: previewUrl || clan.headerImageUrl }} />
          </div>
          <div className="mt-3 flex flex-wrap gap-2">
            <button type="button" className="btn-game" disabled={save.isPending || !previewUrl} onClick={() => { setMsg(""); setErr(""); save.mutate(); }} aria-label="Save this picture as your crew card header background">
              {save.isPending ? "Saving…" : "Save header picture"}
            </button>
            <button type="button" className="btn-ghost" onClick={() => { setImg(null); setImgSrc(""); setErr(""); }} aria-label="Cancel editing the header picture">
              Cancel
            </button>
            <button type="button" className="btn-ghost" onClick={() => fileRef.current?.click()} aria-label="Pick a different header picture">
              Pick a different picture
            </button>
          </div>
          <p className="mt-2 text-[12.5px] leading-relaxed text-[var(--dim)]">JPG or PNG, up to 4 MB. Every picture is safety-checked automatically before it is stored — nude or illegal pictures are blocked. A dark shade is added over the picture on the card so your emblem, name and motto stay readable, and the card never changes size.</p>
        </div>
      )}

      <input
        ref={fileRef}
        type="file"
        accept="image/jpeg,image/png"
        className="hidden"
        aria-label="Choose a header picture file"
        onChange={(e) => { pick(e.target.files?.[0]); e.target.value = ""; }}
      />
    </section>
  );
}

function ClanHome({
  clanId,
  playerKey,
  gamertag,
  onBack,
  goPremium,
}: {
  clanId: number;
  playerKey: string;
  gamertag: string;
  onBack: () => void;
  goPremium?: () => void;
}) {
  const qc = useQueryClient();
  const [applyMsg, setApplyMsg] = useState("");
  const [notice, setNotice] = useState("");
  const [error, setError] = useState("");

  const clan = useQuery({
    queryKey: ["clan", clanId, playerKey],
    queryFn: () => api.getClan({ clanId, playerKey }),
  });
  const invalidate = () => {
    qc.invalidateQueries({ queryKey: ["clan", clanId] });
    qc.invalidateQueries({ queryKey: ["clans"] });
    qc.invalidateQueries({ queryKey: ["clanRankings"] });
    qc.invalidateQueries({ queryKey: ["my-clan"] });
    qc.invalidateQueries({ queryKey: ["profile"] });
    qc.invalidateQueries({ queryKey: ["dm-conversations"] });
  };
  const fail = (e: Error) => setError(e.message);

  const join = useMutation({
    mutationFn: async () =>
      await api.joinClan({ clanId, playerKey, gamertag, platform: "PS5", message: applyMsg }),
    onSuccess: (res) => {
      setError("");
      setNotice(
        res.joined
          ? "Welcome in — you joined as a Recruit. Say hello in chat!"
          : res.requested
            ? res.requestReason === "returning"
              ? "Request sent — you were in this crew before, so there's no direct way back in. Your request is in the crew chat now, and the Leader can accept it there."
              : "Request sent — you already joined a crew this week (one direct join a week, to stop crew-hopping). Your request is in the crew chat now, and the Leader can accept it there."
            : "Application sent. A Leader or Co-Leader will review it.",
      );
      invalidate();
    },
    onError: fail,
  });
  /* Leave crew (owner's direction): any member can leave from
     the crew page. Leaving also leaves the crew chat
     (automatic), and a Leader leaving passes leadership on
     (or dissolves a one-member crew) server-side. */
  const [confirmLeave, setConfirmLeave] = useState(false);
  const leave = useMutation({
    mutationFn: async () => await api.leaveClan({ clanId, playerKey }),
    onSuccess: () => { invalidate(); onBack(); },
    onError: fail,
  });
  /* Crew Settings tabs (owner's direction): Details (Leader
     only), Bio & Rules (Leader and Co-Leaders — the SAME bio /
     rules / requirements fields as Create a Crew Step 2, one
     source of truth) and Crew customisation (Leader only).
     Role management down the rank ladder and application
     review live here too. */
  const [crewError, setCrewError] = useState("");
  const [settingsTab, setSettingsTab] = useState<"details" | "biorules" | "customise">("details");
  const [bioDraft, setBioDraft] = useState("");
  const [bioRulesDraft, setBioRulesDraft] = useState("");
  const [reqDraft, setReqDraft] = useState("");
  const [kickId, setKickId] = useState(0);
  const saveBioRules = useMutation({
    mutationFn: async () => await api.updateCrewBioRules({ clanId, playerKey, description: bioDraft, rules: bioRulesDraft, requirements: reqDraft }),
    onSuccess: () => { setCrewError(""); setNotice("Bio, rules and requirements updated — the crew page and join flow show them now."); invalidate(); },
    onError: (e) => setCrewError(e.message),
  });
  const changeRole = useMutation({
    mutationFn: async (input: { memberId: number; action: "promote" | "demote" | "kick" }) =>
      await api.changeRole({ clanId, playerKey, memberId: input.memberId, action: input.action, reason: input.action === "kick" ? "Removed by crew leadership" : "" }),
    onSuccess: () => { setKickId(0); setCrewError(""); invalidate(); },
    onError: (e) => setCrewError(e.message),
  });
  const reviewApp = useMutation({
    mutationFn: async (input: { applicationId: number; approve: boolean }) =>
      await api.reviewApplication({ clanId, playerKey, applicationId: input.applicationId, approve: input.approve }),
    onSuccess: () => { setError(""); invalidate(); },
    onError: (e) => setCrewError(e.message),
  });
  /* Edit crew details (Leader only). The crew NAME is not in this
     form at all — crew names are permanent, and the server refuses
     renames too. */
  const [editOpen, setEditOpen] = useState(false);
  const [eTag, setETag] = useState("");
  const [eColor, setEColor] = useState("#FF2E88");
  const [eMotto, setEMotto] = useState("");
  const [ePlatform, setEPlatform] = useState<"PS5" | "Xbox" | "Both">("Both");
  const [eRegion, setERegion] = useState("");
  const [eLanguage, setELanguage] = useState("English");
  const [ePlaystyle, setEPlaystyle] = useState("Chill");
  const [ePrivacy, setEPrivacy] = useState<"Public" | "Invite-Only" | "Application">("Public");
  const saveDetails = useMutation({
    mutationFn: async (current: { name: string; description: string; rules: string; requirements: string }) =>
      await api.updateClan({
        clanId, playerKey, name: current.name, tag: eTag, color: eColor, motto: eMotto,
        description: current.description, rules: current.rules, requirements: current.requirements, platform: ePlatform, region: eRegion,
        language: eLanguage, playstyle: ePlaystyle, privacy: ePrivacy,
      }),
    onSuccess: () => { setEditOpen(false); setCrewError(""); setNotice("Crew details updated."); invalidate(); },
    onError: (e) => setCrewError(e.message),
  });

  if (clan.isPending) return <p className="text-sm text-[var(--dim)]">Loading crew…</p>;
  if (clan.error || !clan.data) {
    return (
      <div>
        <button type="button" className="btn-ghost mb-4" onClick={onBack}>← All crews</button>
        <EmptyNote>That crew could not be loaded.</EmptyNote>
      </div>
    );
  }
  const d: ClanDetail = clan.data;
  const c = d.clan;
  const isMember = d.myRole !== "";
  const canManageBioRules = d.myRole === "Leader" || d.myRole === "Co-Leader";
  // The crew's equipped theme is the crew page's accent; without
  // one, the crew colour accents the page.
  const accent = c.themeAccent || c.color;

  return (
    <div>
      <button type="button" className="btn-ghost mb-4" onClick={onBack}>← All crews</button>

      <section className="card overflow-hidden">
        <div className="relative">
          {c.headerImageUrl ? (
            /* The SAME header background as the crew card: the
               Leader's custom header picture leads the crew page
               too, so the crew looks the same in the list and on
               its own page. */
            <div className="relative h-[190px] w-full overflow-hidden sm:h-[220px]" role="img" aria-label={`${c.name}'s custom header picture`}>
              <img decoding="async" src={c.headerImageUrl} alt="" className="absolute inset-0 h-full w-full object-cover" />
            </div>
          ) : c.callingCard && cardDesignOf(c.callingCard) ? (
            <div className="relative h-[190px] w-full sm:h-[220px]" style={{ background: cardDesignOf(c.callingCard)?.background }} role="img" aria-label={`This crew's banner is its ${cardDesignOf(c.callingCard)?.title} calling card`}>
              <CardSceneArt scene={cardDesignOf(c.callingCard)?.scene ?? "skyline"} animated={cardDesignOf(c.callingCard)?.animated ?? false} />
              {cardDesignOf(c.callingCard)?.scene === "founders" ? <span className="cc-shimmer" aria-hidden="true" /> : null}
              <span className="absolute bottom-3 left-4 font-display text-xl font-extrabold uppercase tracking-wide text-white" style={{ textShadow: "0 2px 10px rgba(0,0,0,0.7)" }}>
                {cardDesignOf(c.callingCard)?.title}
              </span>
            </div>
          ) : (
            <div className="h-[190px] w-full sm:h-[220px]" style={{ background: `linear-gradient(135deg, ${accent}55, rgba(11,11,20,0.92) 65%), var(--surface2)` }} role="img" aria-label="This crew has not equipped a calling card banner yet — its crew colour shows here instead" />
          )}
          <div className="absolute inset-0" style={{ background: `linear-gradient(180deg, ${accent}33, rgba(11,11,20,0.88) 88%)` }} />
        </div>
        <div className="relative px-5 pb-5">
          <div className="-mt-14 flex flex-col items-center text-center">
            <span className="block">
              <ClanEmblem tag={c.tag} color={c.color} emblem={c.emblem} effect={c.emblemEffect} finish={c.colorFinish} size={104} />
            </span>
            <h2 className="font-display mt-1 text-3xl uppercase leading-tight"><span style={{ color: c.color }}>[{c.tag}]</span> {c.name}{c.badge ? <span className="ml-2 align-middle rounded-full bg-[var(--accent)] px-2.5 py-1 text-[11px] font-extrabold uppercase tracking-wide text-white">{c.badge}</span> : null}</h2>
            <p className="italic text-[var(--dim)]">{c.motto || "Ready for Leonida"}</p>
            <p className="mt-1.5 text-sm font-bold">Crew tag <span style={{ color: c.color }}>[{c.tag}]</span> <span className="font-semibold text-[var(--dim)]">— every member shows it in front of their name while they are in this crew</span></p>
            <div className="mt-3 flex flex-wrap items-center justify-center gap-2">
              <span className="rounded-full bg-[var(--surface2)] px-3 py-1.5 text-xs font-bold">{PLAYSTYLE_ICONS[c.playstyle] ?? ""} {c.playstyle}</span>
              <span className="rounded-full bg-[var(--surface2)] px-3 py-1.5 text-xs font-bold"> {c.platform}</span>
              <span className="rounded-full bg-[var(--surface2)] px-3 py-1.5 text-xs font-bold"> {c.region || "Worldwide"}</span>
              {isMember && (
                <span className="rounded-full px-3 py-1.5 text-sm font-extrabold" style={{ background: ROLE_COLORS[d.myRole] ?? "var(--surface2)", color: "#fff" }}>
                  {ROLE_ICONS[d.myRole]} You: {d.myRole}
                </span>
              )}
            </div>
          </div>

          {/* Crew stats — four even tiles. "Events" and
              "Events held" are SEPARATE stats again (restored,
              owner's question Nov 22 2026): Events counts the
              Community Events this crew has on the books right
              now (getClan's eventsCount, counted live from the
              events rows it hosts); Events held is the crew's
              lifetime counter, which only ever goes up. */}
          <div className="mx-auto mt-4 grid max-w-xl grid-cols-2 gap-2 sm:grid-cols-4">
            <div className="stat-tile"><div className="num">{c.memberCount}</div><div className="lbl"> Members · Unlimited</div></div>
            <div className="stat-tile"><div className="num">{d.eventsCount}</div><div className="lbl">Events</div></div>
            <div className="stat-tile"><div className="num">{c.eventsHeld}</div><div className="lbl">Events held</div></div>
            <div className="stat-tile"><div className="num">{c.walletCredits}</div><div className="lbl">Crew wallet (VC)</div></div>
          </div>


          {!isMember && (
            <div className="mx-auto mt-4 max-w-xl">
              {(c.rules.trim() || c.requirements.trim()) && (
                <div className="mb-3 rounded-xl border border-[var(--border)] bg-[var(--surface2)] p-3.5 text-left">
                  {c.rules.trim() && (
                    <>
                      <p className="text-sm font-extrabold">Rules</p>
                      <ul className="mt-1.5 grid gap-1">
                        {c.rules.split("\n").map((r) => r.trim()).filter(Boolean).map((r, i) => (
                          <li key={i} className="text-sm leading-relaxed text-[var(--dim)]">• {r}</li>
                        ))}
                      </ul>
                    </>
                  )}
                  {c.requirements.trim() && (
                    <>
                      <p className="mt-3 text-sm font-extrabold">Requirements to join</p>
                      <ul className="mt-1.5 grid gap-1">
                        {c.requirements.split("\n").map((r) => r.trim()).filter(Boolean).map((r, i) => (
                          <li key={i} className="text-sm leading-relaxed text-[var(--dim)]">• {r}</li>
                        ))}
                      </ul>
                    </>
                  )}
                  <p className="mt-2 text-sm font-semibold">By joining you agree to this crew&apos;s rules and meet its requirements.</p>
                </div>
              )}
              <label className="flabel" htmlFor="apply-msg">Message with your application</label>
              <input id="apply-msg" className="field" {...FIELDS.joinClan.message} value={applyMsg} onChange={(e) => setApplyMsg(e.target.value)} placeholder="Why do you want in?" />
              <button
                type="button"
                className="btn-game mt-3 w-full"
                disabled={!gamertag || join.isPending || (c.privacy === "Public" && d.myJoinState.pendingRequest)}
                onClick={() => join.mutate()}
                aria-label={c.privacy === "Public" && d.myJoinState.pendingRequest ? `Your join request for ${c.name} is already with the Leader` : undefined}
              >
                {c.privacy === "Public"
                  ? d.myJoinState.pendingRequest
                    ? "Request sent — waiting for the Leader"
                    : d.myJoinState.directAllowed
                      ? " Join as Recruit"
                      : " Request to join"
                  : " Apply to join"}
              </button>
              {!gamertag && <p className="mt-2 text-center text-sm text-[var(--amber)]">Set your gamertag in your profile first.</p>}
              {c.privacy === "Public" && d.myJoinState.pendingRequest && (
                <p className="mt-2 text-center text-sm leading-relaxed text-[var(--dim)]">Your request is in this crew&apos;s chat — the Leader accepts it there, and you&apos;re in the moment they do.</p>
              )}
              {c.privacy === "Public" && !d.myJoinState.pendingRequest && !d.myJoinState.directAllowed && (
                <p className="mt-2 text-center text-sm leading-relaxed text-[var(--dim)]">
                  {d.myJoinState.reason === "returning"
                    ? "You were in this crew before — coming back needs the Leader's OK, so this sends a request into the crew chat instead of putting you straight back in."
                    : "You already joined a crew this week — one direct join a week, to stop crew-hopping. This sends a request into the crew chat for the Leader to accept instead."}
                </p>
              )}
              <p className="mt-2 text-center text-sm leading-relaxed text-[var(--dim)]">Joining gives you this crew&apos;s Crew tag — <strong style={{ color: c.color }}>[{c.tag}]</strong> shows in front of your name, in this crew&apos;s colour, for as long as you are a member.</p>
            </div>
          )}
          {notice && <p className="mt-3 text-center text-sm font-semibold text-[var(--accent2)]">{notice}</p>}
          {error && <p className="mt-3 text-center text-sm text-[var(--amber)]" role="alert">{error}</p>}
          {isMember && (
            <div className="mx-auto mt-4 max-w-xl border-t border-[var(--border)] pt-4 text-center">
              {!confirmLeave ? (
                <button type="button" className="btn-ghost" onClick={() => setConfirmLeave(true)} aria-label={`Leave ${c.name}`}>Leave crew</button>
              ) : (
                <>
                  <p className="text-sm leading-relaxed text-[var(--dim)]">
                    {d.myRole === "Leader"
                      ? d.members.length > 1
                        ? `Leadership will pass to your highest-ranked member, and you will leave ${c.name} and its crew chat. Your Crew tag [${c.tag}] comes off your name the moment you leave.`
                        : `You are the only member — leaving dissolves ${c.name} and its crew chat, and your Crew tag [${c.tag}] comes off your name.`
                      : `You will leave ${c.name} and its crew chat, and your Crew tag [${c.tag}] comes off your name the moment you leave. You can only be in one crew at a time, so leaving frees you to join another — and you will get that crew's tag instead.`}
                  </p>
                  <p className="mt-1.5 text-sm leading-relaxed text-[var(--dim)]">Heads up: there&apos;s no direct way back into a crew you&apos;ve been in — coming back means sending a request the Leader accepts in the crew chat. And direct crew joins are one a week.</p>
                  <div className="mt-2.5 flex justify-center gap-2">
                    <button type="button" className="btn-game" disabled={leave.isPending} onClick={() => leave.mutate()} aria-label={`Confirm leaving ${c.name}`}>Yes, leave</button>
                    <button type="button" className="btn-ghost" onClick={() => setConfirmLeave(false)}>Stay</button>
                  </div>
                </>
              )}
            </div>
          )}
        </div>
      </section>

      {/* Bio — the crew's about text from creation (the same
          description field edited in Crew Settings → Bio &
          Rules). Shown to everyone; an empty bio gets one short
          line, never a big blank gap. */}
      <section className="card mt-4 p-5" aria-label={`${c.name} bio`}>
        <h3 className="font-display uppercase">Bio</h3>
        {c.description.trim() ? (
          <p className="mt-2 whitespace-pre-line text-sm leading-relaxed text-[var(--dim)]">{c.description}</p>
        ) : canManageBioRules ? (
          <p className="mt-2 text-sm text-[var(--dim)]">No bio yet — add one in Crew Settings → Bio &amp; Rules below, so players know what this crew is about.</p>
        ) : (
          <p className="mt-2 text-sm text-[var(--dim)]">This crew hasn&apos;t added a bio yet.</p>
        )}
      </section>

      {/* Rules & Requirements — the crew's rules and its join
          requirements, one per line, exactly as written in
          Create a Crew Step 2 / Crew Settings → Bio & Rules.
          Shown to everyone, and again in the join flow above. */}
      <section className="card mt-4 p-5" aria-label={`${c.name} rules and requirements`}>
        <h3 className="font-display uppercase">Rules &amp; Requirements</h3>
        <p className="mt-3 text-sm font-extrabold">Rules</p>
        {c.rules.trim() ? (
          <ul className="mt-1.5 grid gap-1.5">
            {c.rules.split("\n").map((r) => r.trim()).filter(Boolean).map((r, i) => (
              <li key={i} className="flex gap-2 text-sm leading-relaxed"><span aria-hidden="true" style={{ color: accent }}>•</span><span>{r}</span></li>
            ))}
          </ul>
        ) : (
          <p className="mt-1.5 text-sm text-[var(--dim)]">No rules set yet{canManageBioRules ? " — add some in Crew Settings → Bio & Rules." : "."}</p>
        )}
        <p className="mt-4 text-sm font-extrabold">Requirements to join</p>
        {c.requirements.trim() ? (
          <ul className="mt-1.5 grid gap-1.5">
            {c.requirements.split("\n").map((r) => r.trim()).filter(Boolean).map((r, i) => (
              <li key={i} className="flex gap-2 text-sm leading-relaxed"><span aria-hidden="true" style={{ color: accent }}>•</span><span>{r}</span></li>
            ))}
          </ul>
        ) : (
          <p className="mt-1.5 text-sm text-[var(--dim)]">No special requirements — everyone is welcome{canManageBioRules ? "; add requirements in Crew Settings → Bio & Rules if that changes" : ""}.</p>
        )}
      </section>

      {/* Members — every member shows the crew tag in front of
          their name, rendered live from their membership: it is
          here while they are in the crew and gone the moment they
          leave or are kicked. */}
      <section className="card mt-4 p-5" aria-label={`${c.name} members`}>
        <h3 className="font-display uppercase">Members · {d.members.length} <span className="text-sm font-bold normal-case text-[var(--dim)]">— unlimited spots</span></h3>
        {crewError && <p className="mt-2 text-sm font-semibold text-[#ff6b81]" role="alert">{crewError}</p>}
        <ul className="mt-3 grid gap-2">
          {d.members.map((m) => {
            const RANK: Record<string, number> = { Leader: 5, "Co-Leader": 4, Elder: 3, Member: 2, Recruit: 1 };
            const myRank = RANK[d.myRole] ?? 0;
            const canManage = !m.isMe && myRank > (RANK[m.role] ?? 0) && (d.myRole === "Leader" || d.myRole === "Co-Leader" || d.myRole === "Elder");
            return (
              <li key={m.id} className="flex flex-wrap items-center gap-2.5 rounded-xl border border-[var(--border)] px-3 py-2.5">
                <CosmeticAvatar name={m.gamertag} size={38} avatarUrl={m.avatarUrl} />
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-[15px] font-bold">
                    <span className="mr-1.5 inline-block rounded-md px-1.5 py-0.5 align-middle text-[11px] font-extrabold" style={{ background: "var(--surface2)", color: c.color, border: `1px solid ${c.color}` }}>[{c.tag}]</span>
                    {m.gamertag}
                    {m.isMe && <span className="ml-1.5 text-[12px] font-semibold text-[var(--dim)]">(you)</span>}
                  </span>
                  <span className="block text-[12px] text-[var(--dim)]">{m.platform} · joined {new Date(m.joinedAt).toLocaleDateString()}</span>
                </span>
                <span className="flex-none rounded-full px-2.5 py-1 text-[11.5px] font-extrabold" style={{ background: ROLE_COLORS[m.role] ?? "var(--surface2)", color: "#fff" }}>{ROLE_ICONS[m.role]} {m.role}</span>
                {canManage && kickId !== m.id && (
                  <span className="flex flex-none gap-1.5">
                    {m.role !== "Co-Leader" && m.role !== "Leader" && (
                      <button type="button" className="btn-ghost" style={{ minHeight: 32, padding: "3px 10px", fontSize: 12 }} disabled={changeRole.isPending} onClick={() => changeRole.mutate({ memberId: m.id, action: "promote" })} aria-label={`Promote ${m.gamertag}`}>Promote</button>
                    )}
                    {m.role !== "Recruit" && (
                      <button type="button" className="btn-ghost" style={{ minHeight: 32, padding: "3px 10px", fontSize: 12 }} disabled={changeRole.isPending} onClick={() => changeRole.mutate({ memberId: m.id, action: "demote" })} aria-label={`Demote ${m.gamertag}`}>Demote</button>
                    )}
                    <button type="button" className="btn-ghost" style={{ minHeight: 32, padding: "3px 10px", fontSize: 12 }} disabled={changeRole.isPending} onClick={() => setKickId(m.id)} aria-label={`Kick ${m.gamertag} from ${c.name}`}>Kick</button>
                  </span>
                )}
                {canManage && kickId === m.id && (
                  <span className="flex flex-none items-center gap-1.5">
                    <span className="text-[12.5px] font-semibold text-[var(--dim)]">Kick {m.gamertag}? Their [{c.tag}] tag comes off at once.</span>
                    <button type="button" className="btn-game" style={{ minHeight: 32, padding: "3px 10px", fontSize: 12 }} disabled={changeRole.isPending} onClick={() => changeRole.mutate({ memberId: m.id, action: "kick" })} aria-label={`Confirm kicking ${m.gamertag}`}>Yes, kick</button>
                    <button type="button" className="btn-ghost" style={{ minHeight: 32, padding: "3px 10px", fontSize: 12 }} onClick={() => setKickId(0)}>Cancel</button>
                  </span>
                )}
              </li>
            );
          })}
        </ul>
        <p className="mt-3 text-[12.5px] leading-relaxed text-[var(--dim)]">Only a higher rank can promote, demote or kick a lower one. Every change is logged.</p>
      </section>

      {d.applications.length > 0 && (d.myRole === "Leader" || d.myRole === "Co-Leader") && (
        <section className="card mt-4 p-5" aria-label="Pending applications">
          <h3 className="font-display uppercase">Applications · {d.applications.length}</h3>
          <ul className="mt-3 grid gap-2">
            {d.applications.map((a) => (
              <li key={a.id} className="flex flex-wrap items-center gap-2.5 rounded-xl border border-[var(--border)] px-3 py-2.5">
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-[15px] font-bold">{a.gamertag}</span>
                  {a.kind === "join_request" && <span className="block text-[12px] font-bold text-[var(--dim)]">Join request — couldn&apos;t join directly, so it&apos;s waiting on the Leader (it&apos;s also a card in the crew chat).</span>}
                  {a.message && <span className="block truncate text-[13px] text-[var(--dim)]">“{a.message}”</span>}
                </span>
                {a.kind === "join_request" && d.myRole !== "Leader" ? (
                  <span className="flex-none text-[12.5px] font-bold text-[var(--dim)]">Leader decides</span>
                ) : (
                  <>
                    <button type="button" className="btn-game" style={{ minHeight: 34, padding: "4px 12px", fontSize: 13 }} disabled={reviewApp.isPending} onClick={() => reviewApp.mutate({ applicationId: a.id, approve: true })} aria-label={`Approve ${a.gamertag}'s application`}>Approve</button>
                    <button type="button" className="btn-ghost" style={{ minHeight: 34, padding: "4px 12px", fontSize: 13 }} disabled={reviewApp.isPending} onClick={() => reviewApp.mutate({ applicationId: a.id, approve: false })} aria-label={`Decline ${a.gamertag}'s application`}>Decline</button>
                  </>
                )}
              </li>
            ))}
          </ul>
        </section>
      )}

      {d.activity.length > 0 && (
        <section className="card mt-4 p-5" aria-label={`${c.name} activity log`}>
          <h3 className="font-display uppercase">Activity</h3>
          <ul className="mt-3 grid gap-1.5">
            {d.activity.slice(0, 20).map((a) => (
              <li key={a.id} className="flex items-baseline gap-2 text-sm">
                <span className="min-w-0 flex-1 leading-relaxed"><strong>{a.actor}</strong> {a.action}{a.target ? <> <strong>{a.target}</strong></> : ""}{a.reason ? <span className="text-[var(--dim)]"> — {a.reason}</span> : ""}</span>
                <span className="flex-none text-[12px] text-[var(--dim)]">{timeAgo(a.createdAt)}</span>
              </li>
            ))}
          </ul>
        </section>
      )}

      {(d.myRole === "Leader" || d.myRole === "Co-Leader") && (
        <section className="card mt-4 p-5" aria-label="Crew settings">
          <div className="flex flex-wrap items-center gap-2">
            <h3 className="font-display uppercase">Crew settings</h3>
            <div className="ml-auto flex flex-wrap gap-1.5" role="tablist" aria-label="Crew settings sections">
              {d.myRole === "Leader" && (
                <button type="button" role="tab" aria-selected={settingsTab === "details"} className={settingsTab === "details" ? "btn-game" : "btn-ghost"} style={{ minHeight: 36, padding: "5px 12px", fontSize: 13 }} onClick={() => setSettingsTab("details")}>Details</button>
              )}
              <button type="button" role="tab" aria-selected={settingsTab === "biorules"} className={settingsTab === "biorules" ? "btn-game" : "btn-ghost"} style={{ minHeight: 36, padding: "5px 12px", fontSize: 13 }} onClick={() => { setSettingsTab("biorules"); setBioDraft(c.description); setBioRulesDraft(c.rules); setReqDraft(c.requirements); }}>Bio &amp; Rules</button>
              {d.myRole === "Leader" && (
                <button type="button" role="tab" aria-selected={settingsTab === "customise"} className={settingsTab === "customise" ? "btn-game" : "btn-ghost"} style={{ minHeight: 36, padding: "5px 12px", fontSize: 13 }} onClick={() => setSettingsTab("customise")}>Crew customisation</button>
              )}
            </div>
          </div>
          {crewError && settingsTab !== "customise" && <p className="mt-2 text-sm font-semibold text-[#ff6b81]" role="alert">{crewError}</p>}

          {settingsTab === "details" && d.myRole === "Leader" && (
            <div className="mt-3">
              {!editOpen ? (
                <button
                  type="button"
                  className="btn-ghost"
                  style={{ minHeight: 36, padding: "5px 12px", fontSize: 13 }}
                  onClick={() => {
                    setETag(c.tag); setEColor(c.color); setEMotto(c.motto);
                    setEPlatform((["PS5", "Xbox", "Both"].includes(c.platform) ? c.platform : "Both") as "PS5" | "Xbox" | "Both"); setERegion(c.region); setELanguage(c.language);
                    setEPlaystyle(c.playstyle); setEPrivacy((["Public", "Invite-Only", "Application"].includes(c.privacy) ? c.privacy : "Public") as "Public" | "Invite-Only" | "Application"); setEditOpen(true);
                  }}
                  aria-label={`Edit ${c.name} details`}
                >
                  Edit crew details
                </button>
              ) : (
                <div>
                  <label className="flabel" htmlFor="crew-edit-name">Crew name</label>
                  <input id="crew-edit-name" className="field" {...FIELDS.updateClan.name} value={c.name} disabled aria-describedby="crew-name-permanent" />
                  <p id="crew-name-permanent" className="mt-1.5 text-[13px] font-semibold" style={{ color: "var(--amber)" }}>Crew names are permanent — the name can&apos;t be changed after creation.</p>
                  <div className="grid gap-0 sm:grid-cols-2 sm:gap-x-4">
                    <div>
                      <label className="flabel" htmlFor="crew-edit-tag">Crew tag (2–4 characters)</label>
                      <input id="crew-edit-tag" className="field" {...FIELDS.updateClan.tag} value={eTag} onChange={(e) => setETag(e.target.value.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 4))} autoComplete="off" />
                    </div>
                    <div>
                      <label className="flabel" htmlFor="crew-edit-motto">Motto</label>
                      <input id="crew-edit-motto" className="field" {...FIELDS.updateClan.motto} value={eMotto} onChange={(e) => setEMotto(e.target.value)} />
                    </div>
                    <div>
                      <label className="flabel" htmlFor="crew-edit-platform">Platform</label>
                      <select id="crew-edit-platform" className="field" value={ePlatform} onChange={(e) => setEPlatform(e.target.value as typeof ePlatform)}>
                        <option>PS5</option><option>Xbox</option><option>Both</option>
                      </select>
                    </div>
                    <div>
                      <label className="flabel" htmlFor="crew-edit-privacy">Who can join</label>
                      <select id="crew-edit-privacy" className="field" value={ePrivacy} onChange={(e) => setEPrivacy(e.target.value as typeof ePrivacy)}>
                        <option>Public</option><option>Application</option><option>Invite-Only</option>
                      </select>
                    </div>
                    <div>
                      <label className="flabel" htmlFor="crew-edit-playstyle">Playstyle</label>
                      <select id="crew-edit-playstyle" className="field" value={ePlaystyle} onChange={(e) => setEPlaystyle(e.target.value)}>
                        {PLAYSTYLES.map((p) => <option key={p}>{p}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="flabel" htmlFor="crew-edit-region">Region</label>
                      <input id="crew-edit-region" className="field" {...FIELDS.updateClan.region} value={eRegion} onChange={(e) => setERegion(e.target.value)} />
                    </div>
                    <div>
                      <label className="flabel" htmlFor="crew-edit-lang">Language</label>
                      <input id="crew-edit-lang" className="field" {...FIELDS.updateClan.language} value={eLanguage} onChange={(e) => setELanguage(e.target.value)} />
                    </div>
                    <div>
                      <span className="flabel" id="crew-edit-color-label">Crew colour</span>
                      <div className="flex flex-wrap items-center gap-2" role="group" aria-labelledby="crew-edit-color-label">
                        {CREW_CATALOGUE_COLORS.map((col) => (
                          <button key={col.value} type="button" className="swatch" style={{ background: col.value }} aria-pressed={eColor.toLowerCase() === col.value.toLowerCase()} onClick={() => setEColor(col.value)} aria-label={`Crew colour ${col.name}`} />
                        ))}
                      </div>
                      <p className="mt-1.5 text-[12.5px] text-[var(--dim)]">The Crew Colours catalogue — the same colours as Crew customisation, and every named colour is free. The custom colour tool below is part of Premium{d.ownerPremiumActive ? " — your Premium is on, so any colour you pick applies" : " — it unlocks while the crew's owner has Premium; finishes like Chrome live in the Crew customisation tab"}.</p>
                      <p className="mt-3 text-[12.5px] font-bold">Or a custom colour — any colour you like{d.ownerPremiumActive ? "" : " — Premium"}:</p>
                      <div className="mt-1.5">
                        <CustomColorControl id="crew-edit-custom-color" value={eColor} onChange={setEColor} fieldProps={FIELDS.updateClan.color} disabled={!d.ownerPremiumActive} />
                      </div>
                    </div>
                  </div>
                  <p className="mt-2 text-[13px] text-[var(--dim)]">Bio, rules and requirements live in the Bio &amp; Rules tab — one place, no duplicates. Members: Unlimited — crews have no member cap, so there is no cap to set here.</p>
                  <div className="mt-3 flex gap-2">
                    <button type="button" className="btn-game" disabled={saveDetails.isPending} onClick={() => saveDetails.mutate({ name: c.name, description: c.description, rules: c.rules, requirements: c.requirements })} aria-label="Save crew details">Save details</button>
                    <button type="button" className="btn-ghost" onClick={() => setEditOpen(false)}>Cancel</button>
                  </div>
                </div>
              )}
            </div>
          )}

          {settingsTab === "biorules" && (
            <div className="mt-3">
              <p className="text-[13px] leading-relaxed text-[var(--dim)]">These are the same fields as Create a Crew Step 2 — editing them here updates the crew page&apos;s Bio and Rules &amp; Requirements sections and the join flow straight away.</p>
              <label className="flabel" htmlFor="crew-bio-edit">Bio — what is this crew about?</label>
              <textarea id="crew-bio-edit" className="field" rows={4} {...FIELDS.updateCrewBioRules.description} value={bioDraft} onChange={(e) => setBioDraft(e.target.value)} placeholder="Tell players what this crew does, when you play, and what you are about." />
              <label className="flabel" htmlFor="crew-rules-edit2">Rules — one rule per line</label>
              <textarea id="crew-rules-edit2" className="field" rows={4} {...FIELDS.updateCrewBioRules.rules} value={bioRulesDraft} onChange={(e) => setBioRulesDraft(e.target.value)} placeholder={"One rule per line, e.g.\nNo team-killing\nBe on for crew nights"} />
              <label className="flabel" htmlFor="crew-req-edit">Requirements to join — one per line</label>
              <textarea id="crew-req-edit" className="field" rows={3} {...FIELDS.updateCrewBioRules.requirements} value={reqDraft} onChange={(e) => setReqDraft(e.target.value)} placeholder={"One per line, e.g.\nPS5 only\nMic preferred\nActive most weekends"} />
              <div className="mt-3 flex gap-2">
                <button type="button" className="btn-game" disabled={saveBioRules.isPending} onClick={() => saveBioRules.mutate()} aria-label="Save bio, rules and requirements">Save bio &amp; rules</button>
              </div>
            </div>
          )}

          {settingsTab === "customise" && d.myRole === "Leader" && (
            <div>
              {/* Header background sits in Crew Settings alongside
                  the customisation sections (owner's direction):
                  Leader-only, like everything in this tab. */}
              <CrewHeaderBackgroundEditor clan={c} playerKey={playerKey} onChanged={invalidate} />
              <CrewCustomisationPanel clanId={clanId} playerKey={playerKey} clanName={c.name} clanColor={c.color} clanFinish={c.colorFinish} clanTag={c.tag} clanEmblem={c.emblem} clanEffect={c.emblemEffect} goPremium={goPremium} />
            </div>
          )}
        </section>
      )}

    </div>
  );
}

/* --------------------------------- EVENTS --------------------------------- */

function eventArtForType(type: string): { img: string; alt: string } {
  switch (type) {
    case "Race / Street Race":
    case "Street Racing":
    case "Time Trial":
      return { img: eventTypeRaceUrl, alt: "Original ViceSunshine illustration of two sports cars street racing through neon streets at dusk — the racing theme picture" };
    case "Off-Road / Mud Club Racing":
      return { img: eventTypeOffroadUrl, alt: "Original ViceSunshine illustration of trucks splashing through swamp mud at dusk — the off-road theme picture" };
    case "Crew Event":
      return { img: eventTypeCrewUrl, alt: "Original ViceSunshine illustration of two crews facing off with armoured vehicles and a tank under neon lights — the crew war theme picture" };
    case "Cruise / Convoy":
    case "Screenshot Contest":
      return { img: eventTypeCruiseUrl, alt: "Original ViceSunshine illustration of a car convoy cruising a coastal highway at sunset — the cruise theme picture" };
    case "Easter Egg Hunt":
      return { img: eventTypeHuntUrl, alt: "Original ViceSunshine illustration of a glowing hidden landmark in a misty swamp at night — the Easter egg hunt theme picture" };
    case "Fashion / Outfit Contest":
      return { img: eventTypeFashionUrl, alt: "Original ViceSunshine illustration of stylish characters on a neon boardwalk runway — the fashion theme picture" };
    case "Watch Party":
      return { img: eventTypeWatchUrl, alt: "Original ViceSunshine illustration of friends watching a huge outdoor cinema screen on a beach at night — the watch party theme picture" };
    default:
      return { img: eventsPromoUrl, alt: "Original ViceSunshine illustration of a community car meet at dusk — the car meet theme picture" };
  }
}

const EVENT_TYPES = ["Car Meet", "Race / Street Race", "Street Racing", "Off-Road / Mud Club Racing", "Time Trial", "Screenshot Contest", "Crew Event", "Cruise / Convoy", "Easter Egg Hunt", "Fashion / Outfit Contest", "Watch Party"];
const POPULAR_EVENT_TAGS = ["carmeet", "race", "timetrial", "screenshot", "crew", "easteregg", "offroad", "cruise", "watchparty", "contest"];

type EventItemT = ApiResponse<typeof api, "listEvents">["items"][number];

function formatCountdown(ms: number): string {
  const total = Math.max(0, Math.floor(ms / 1000));
  const d = Math.floor(total / 86400);
  const h = Math.floor((total % 86400) / 3600);
  const m = Math.floor((total % 3600) / 60);
  const sec = total % 60;
  const pad = (n: number) => String(n).padStart(2, "0");
  return d > 0 ? `${d}d ${pad(h)}:${pad(m)}:${pad(sec)}` : `${pad(h)}:${pad(m)}:${pad(sec)}`;
}

function fmtEventWhen(iso: string, tz: string) {
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return iso;
  try {
    return new Intl.DateTimeFormat("en-US", {
      weekday: "short", month: "short", day: "numeric",
      hour: "numeric", minute: "2-digit", timeZone: tz, timeZoneName: "short",
    }).format(d);
  } catch {
    return d.toLocaleString();
  }
}

function EventCard({
  ev,
  playerKey,
  gamertag,
  onTag,
  savedStore,
  trackedStore,
}: {
  ev: EventItemT;
  playerKey: string;
  gamertag: string;
  onTag: (tag: string) => void;
  savedStore: ReturnType<typeof useSaved>;
  trackedStore: ReturnType<typeof useTrackedGoals>;
}) {
  const qc = useQueryClient();
  const [open, setOpen] = useState(false);
  const [error, setError] = useState("");
  const [resultsDraft, setResultsDraft] = useState("");
  const [first, setFirst] = useState("");
  const [second, setSecond] = useState("");
  const [third, setThird] = useState("");
  const [hostMsg, setHostMsg] = useState("");
  const [copied, setCopied] = useState(false);
  const attendees = useQuery({
    queryKey: ["attendees", ev.id],
    queryFn: () => api.eventAttendees({ eventId: ev.id }),
    enabled: open,
  });
  const invalidate = () => {
    qc.invalidateQueries({ queryKey: ["events"] });
    qc.invalidateQueries({ queryKey: ["attendees"] });
    qc.invalidateQueries({ queryKey: ["inviteEvent"] });
  };
  const rsvp = useMutation({
    mutationFn: async (status: "Going" | "Maybe" | "Can't Go") =>
      await api.rsvpEvent({ playerKey, gamertag, eventId: ev.id, status, inviteCode: ev.inviteCode ?? "" }),
    onSuccess: () => { setError(""); invalidate(); },
    onError: (e) => setError(e.message),
  });
  const saveResults = useMutation({
    mutationFn: async () => await api.setEventResults({ playerKey, gamertag, eventId: ev.id, results: resultsDraft }),
    onSuccess: () => { setResultsDraft(""); setError(""); invalidate(); },
    onError: (e) => setError(e.message),
  });
  // Leader controls — only rendered when ev.canManage (the server
  // re-checks leadership in updateEvent / deleteEvent regardless).
  const [showEdit, setShowEdit] = useState(false);
  const [confirmRemove, setConfirmRemove] = useState(false);
  const [manageMsg, setManageMsg] = useState("");
  const [eTitle, setETitle] = useState("");
  const [eType, setEType] = useState("Car Meet");
  const [eStartsAt, setEStartsAt] = useState("");
  const [eTimezone, setETimezone] = useState("America/New_York");
  const [ePlat, setEPlat] = useState<"PS5" | "Xbox" | "Both">("Both");
  const [eMax, setEMax] = useState(16);
  const [ePrize, setEPrize] = useState("");
  const [eVisibility, setEVisibility] = useState<"Public" | "Private">("Public");
  const [eTags, setETags] = useState("");
  const [eDesc, setEDesc] = useState("");
  const [eRules, setERules] = useState("");
  const [eLobby, setELobby] = useState("");
  const [eLobbyLink, setELobbyLink] = useState("");
  const openEdit = () => {
    setETitle(ev.title);
    setEType(ev.type);
    setEStartsAt(ev.startsAt.slice(0, 16));
    setETimezone(ev.timezone);
    setEPlat((["PS5", "Xbox", "Both"].includes(ev.platform) ? ev.platform : "Both") as "PS5" | "Xbox" | "Both");
    setEMax(ev.maxPlayers);
    setEPrize(ev.prize);
    setEVisibility(ev.visibility === "Private" ? "Private" : "Public");
    setETags(ev.hashtags.map((t) => `#${t}`).join(" "));
    setEDesc(ev.description);
    setERules(ev.rules);
    setELobby(ev.lobbyDetails);
    setELobbyLink(ev.lobbyLink);
    setManageMsg("");
    setShowEdit(true);
  };
  const updateEv = useMutation({
    mutationFn: async () =>
      await api.updateEvent({
        playerKey, gamertag, eventId: ev.id,
        title: eTitle, type: eType, startsAt: eStartsAt, timezone: eTimezone,
        platform: ePlat, maxPlayers: eMax, description: eDesc, rules: eRules,
        prize: ePrize, visibility: eVisibility, hashtags: eTags,
        lobbyDetails: eLobby, lobbyLink: eLobbyLink,
      }),
    onSuccess: () => {
      setShowEdit(false);
      setManageMsg(eVisibility === "Private"
        ? "Event updated — it is now Private. A fresh invite code is on the event card above; share the link or code with the people you want there."
        : "Event updated — it is Public, listed for everyone to find by name or hashtag.");
      setError("");
      invalidate();
    },
    onError: (e) => setError(e.message),
  });
  const [picMsg, setPicMsg] = useState("");
  const setPic = useMutation({
    mutationFn: async (f: File) => {
      const { dataBase64, mimeType } = await optimizedPhotoUpload(f, 1600);
      return await api.setEventImage({ playerKey, gamertag, eventId: ev.id, filename: f.name, mimeType, dataBase64 });
    },
    onSuccess: () => { setPicMsg("Picture saved — it is the banner on this event's card now."); invalidate(); },
    onError: (e) => setPicMsg(e.message),
  });
  const removePic = useMutation({
    mutationFn: async () => await api.removeEventImage({ playerKey, gamertag, eventId: ev.id }),
    onSuccess: () => { setPicMsg("Picture removed — the standard events artwork shows instead."); invalidate(); },
    onError: (e) => setPicMsg(e.message),
  });
  const removeAttendee = useMutation({
    mutationFn: async (attendeeKey: string) => await api.removeEventAttendee({ playerKey, gamertag, eventId: ev.id, attendeeKey }),
    onSuccess: () => { setError(""); invalidate(); },
    onError: (e) => setError(e.message),
  });
  const deleteEv = useMutation({
    mutationFn: async () => await api.deleteEvent({ playerKey, gamertag, eventId: ev.id }),
    onSuccess: () => { setConfirmRemove(false); setError(""); invalidate(); },
    onError: (e) => setError(e.message),
  });
  const hostConfirm = useMutation({
    mutationFn: async () => await api.hostConfirmEvent({ playerKey, gamertag, eventId: ev.id, first, second, third }),
    onSuccess: (res) => {
      setHostMsg(res.confirmed > 0 ? `Results confirmed — Rank Points paid to ${res.confirmed} winner${res.confirmed === 1 ? "" : "s"} automatically${res.clanCreditsPaid > 0 ? `, and ${res.clanCreditsPaid} Vice Credits paid to crew wallets (Event Rewards)` : ""}.${res.skipped.length ? ` Skipped (no ViceSunshine profile): ${res.skipped.join(", ")}.` : ""}` : "No new points paid — those results were already confirmed once.");
      setError("");
      invalidate();
    },
    onError: (e) => setError(e.message),
  });
  const copyInvite = async () => {
    const text = `You're invited to my private ViceSunshine Community Event "${ev.title}" (${fmtEventWhen(ev.startsAt, ev.timezone)}). Open ViceSunshine, go to Events, tap "Join with an invite code" and enter: ${ev.inviteCode}. Or add #event=${ev.inviteCode} to the end of the ViceSunshine link and open it.`;
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
      window.setTimeout(() => setCopied(false), 2500);
    } catch {
      setCopied(false);
      setError("Copy didn't work here — the invite code is shown below, just read it out or type it.");
    }
  };
  // Live countdown to the start (owner's direction): ticks every
  // second while the card is on screen.
  const [nowTick, setNowTick] = useState(() => Date.now());
  useEffect(() => {
    const t = window.setInterval(() => setNowTick(Date.now()), 1000);
    return () => window.clearInterval(t);
  }, []);
  const startMs = new Date(ev.startsAt).getTime();
  const nowMs = nowTick;
  const live = !Number.isNaN(startMs) && nowMs >= startMs - 15 * 60000 && nowMs <= startMs + 4 * 3600000;
  const soon = !Number.isNaN(startMs) && !live && startMs - nowMs > 0 && startMs - nowMs <= 3600000;
  const isHost = Boolean(gamertag) && ev.host.toLowerCase() === gamertag.toLowerCase();
  const countdownText = !Number.isNaN(startMs) && startMs > nowMs ? formatCountdown(startMs - nowMs) : "";
  return (
    <article className="card overflow-hidden">
      <div className="relative h-[120px] w-full sm:h-[168px]">
        <img decoding="async"
          src={ev.imageUrl || eventArtForType(ev.type).img}
          alt={ev.imageUrl ? `Picture for ${ev.title}, uploaded by the host` : eventArtForType(ev.type).alt}
          className="h-full w-full object-cover"
          loading="lazy"
        />
        <div className="absolute inset-0" style={{ background: "linear-gradient(180deg, rgba(11,11,20,0.05) 40%, rgba(11,11,20,0.62))" }} aria-hidden="true" />
        <span className="absolute bottom-3 left-4 rounded-full bg-[rgba(11,11,20,0.85)] px-3 py-1.5 text-[12.5px] font-extrabold text-white" role="timer" aria-label={live ? `${ev.title} is live now` : countdownText ? `${ev.title} starts in ${countdownText}` : `${ev.title} has ended`}>
          {live ? "Live now" : countdownText ? `Starts in ${countdownText}` : "Ended"}
        </span>
        <span className="absolute bottom-3 right-4 rounded-full bg-[rgba(11,11,20,0.85)] px-3 py-1.5 text-[12.5px] font-bold text-white">{ev.going}/{ev.maxPlayers} going</span>
      </div>
      <div className="p-3.5 sm:p-5">
      <div className="flex flex-wrap items-center gap-1.5 sm:gap-2">
        <span className="rounded-full bg-[var(--accent)] px-2.5 py-0.5 text-xs font-bold text-white">Community Event</span>
        <span className="rounded-full bg-[var(--surface2)] px-2.5 py-0.5 text-xs font-bold">{ev.type}</span>
        <span className="rounded-full bg-[var(--surface2)] px-2.5 py-0.5 text-xs font-bold">{ev.platform}</span>
        {ev.visibility === "Private" ? (
          <span className="rounded-full px-2.5 py-0.5 text-xs font-extrabold" style={{ border: "1px solid var(--amber)", color: "var(--amber)" }}>Private — invite only</span>
        ) : (
          <span className="rounded-full px-2.5 py-0.5 text-xs font-extrabold" style={{ border: "1px solid var(--accent2)", color: "var(--accent2)" }}>Public — anyone can join</span>
        )}
        {ev.canManage && <span className="rounded-full bg-[var(--amber)] px-2.5 py-0.5 text-xs font-extrabold text-black">You manage this event — crew Leader</span>}
        {ev.isExample && <span className="rounded-full px-2.5 py-0.5 text-xs font-bold" style={{ border: "1px solid var(--accent2)", color: "var(--accent2)" }}>Community example</span>}
        {ev.earlyAccess && ev.canRsvpGoing && <span className="rounded-full px-2.5 py-0.5 text-xs font-bold" style={{ border: "1px solid var(--amber)", color: "var(--amber)" }}>Premium early access — you&apos;re in early</span>}
        {ev.earlyAccess && !ev.canRsvpGoing && <span className="rounded-full px-2.5 py-0.5 text-xs font-bold" style={{ border: "1px solid var(--amber)", color: "var(--amber)" }}>Premium early access — Going opens {ev.earlyAccessUntil} for everyone</span>}
        {live && <span className="rounded-full bg-[var(--accent2)] px-2.5 py-0.5 text-xs font-extrabold text-[#04211d]">Live now</span>}
        {soon && ev.myRsvp === "Going" && <span className="rounded-full px-2.5 py-0.5 text-xs font-bold" style={{ border: "1px solid var(--amber)", color: "var(--amber)" }}>Starts within the hour — your reminder</span>}
      </div>
      <h3 className="mt-2 text-[15px] font-bold sm:text-lg">{ev.title}</h3>
      <p className="mt-1 text-[13px] font-semibold text-[var(--accent2)] sm:text-sm">{fmtEventWhen(ev.startsAt, ev.timezone)}</p>
      <p className="text-[13px] text-[var(--dim)] sm:text-sm">
        Hosted by {ev.host || "the community"}{ev.hostClanName ? <> · <strong className="text-[var(--text)]">{ev.hostClanName}</strong> crew</> : ""} · max {ev.maxPlayers} players (GTA lobby limit: 32) · {ev.spotsLeft > 0 ? `${ev.spotsLeft} spot${ev.spotsLeft === 1 ? "" : "s"} left` : "Full"} · {ev.prize}
      </p>
      {ev.hashtags.length > 0 && (
        <div className="mt-2 flex flex-wrap gap-1.5">
          {ev.hashtags.map((t) => (
            <button key={t} type="button" className="chip" style={{ minHeight: 32, padding: "2px 10px", fontSize: 12 }} onClick={() => onTag(t)} aria-label={`Show events tagged #${t}`}>
              #{t}
            </button>
          ))}
        </div>
      )}
      {ev.description && <p className="mt-2 line-clamp-3 text-[13px] leading-relaxed text-[var(--dim)] sm:line-clamp-none sm:text-sm">{ev.description}</p>}
      {ev.rules && <p className="mt-1 line-clamp-2 text-[13px] text-[var(--dim)] sm:line-clamp-none sm:text-sm"><strong className="text-[var(--text)]">Rules:</strong> {ev.rules}</p>}
      {ev.results && (
        <p className="mt-2 rounded-lg bg-[var(--surface2)] p-3 text-sm whitespace-pre-line">
          <strong className="text-[var(--amber)]">Results:</strong> {ev.results}
        </p>
      )}
      {ev.visibility === "Private" && ev.inviteCode && (
        <div className="mt-3 rounded-xl border border-[var(--amber)] bg-[var(--surface2)] p-3">
          <p className="text-sm font-extrabold" style={{ color: "var(--amber)" }}>Invite people to this private event</p>
          <p className="mt-1 text-xs leading-relaxed text-[var(--dim)]">This event is hidden from everyone except {ev.hostClanName || "the host crew"} — and anyone you invite. Share the invite code, or send the invite link (the ViceSunshine link with <span className="font-mono">#event={ev.inviteCode}</span> added at the end).</p>
          <div className="mt-2 flex flex-wrap items-center gap-2">
            <span className="rounded-lg bg-[var(--surface)] px-3 py-2 font-mono text-base font-extrabold tracking-[0.2em]" aria-label={`Invite code ${ev.inviteCode}`}>{ev.inviteCode}</span>
            <button type="button" className="btn-primary" style={{ minHeight: 40, padding: "6px 14px", fontSize: 13 }} onClick={copyInvite} aria-label={`Copy the invite for ${ev.title}`}>
              {copied ? "Invite copied" : "Copy invite"}
            </button>
          </div>
        </div>
      )}
      {ev.myRsvp === "Going" && (ev.lobbyDetails || ev.lobbyLink) ? (
        <div className="mt-3 rounded-xl border border-[var(--accent2)] bg-[var(--surface2)] p-3">
          <p className="text-sm font-extrabold text-[var(--accent2)]">Lobby details — for RSVP&apos;d players only</p>
          <p className="mt-1 text-xs text-[var(--dim)]">Lobby details are shared by the host, only for RSVP&apos;d players.</p>
          {ev.lobbyDetails && <p className="mt-2 whitespace-pre-line text-sm leading-relaxed">{ev.lobbyDetails}</p>}
          <p className="mt-1 text-sm text-[var(--dim)]">Host: {ev.host}</p>
          <div className="mt-2 flex flex-wrap gap-2">
            {ev.lobbyLink && (
              <a className="btn-primary" style={{ minHeight: 44, padding: "8px 18px" }} href={ev.lobbyLink} target="_blank" rel="noreferrer" aria-label={ev.lobbyLink.toLowerCase().includes("discord") ? `Open the Discord for ${ev.title} — for joined players only` : `Join the lobby for ${ev.title} via the host's link`}>
                {ev.lobbyLink.toLowerCase().includes("discord") ? "Open Discord" : "Join Lobby"}
              </a>
            )}
            {!ev.lobbyLink && <span className="text-sm font-semibold">Join using the host details above — the Join Lobby link appears here when the host adds one.</span>}
          </div>
        </div>
      ) : (
        <p className="mt-2 text-xs text-[var(--dim)]">RSVP Going to see the lobby details and the host&apos;s Discord link or code — only players who join can see them. The host adds them when creating the event; Discord is optional.</p>
      )}
      {error && <p className="mt-2 text-sm text-[var(--amber)]" role="alert">{error}</p>}
      {ev.kicked && (
        <p className="mt-3 rounded-lg border border-[var(--accent)] p-3 text-sm font-semibold" role="status">
          The host removed you from this event — you can&apos;t join it again. If you think that was a mistake, talk to the host crew&apos;s Leader.
        </p>
      )}
      <div className="mt-3 flex flex-wrap items-center gap-2">
        <span className="text-sm font-semibold">{ev.going} going · {ev.maybe} maybe</span>
        {(["Going", "Maybe", "Can't Go"] as const).map((st) => {
          const goingLocked = st === "Going" && !ev.canRsvpGoing;
          return (
            <button
              key={st}
              type="button"
              className="chip"
              aria-pressed={ev.myRsvp === st}
              disabled={!gamertag || rsvp.isPending || goingLocked || ev.kicked}
              onClick={() => rsvp.mutate(st)}
              aria-label={goingLocked ? `RSVP Going for ${ev.title} — Premium early access, opens ${ev.earlyAccessUntil} for everyone` : `RSVP ${st} for ${ev.title}`}
            >
              {goingLocked ? "Going — Premium early access" : st}
            </button>
          );
        })}
      </div>
      <div className="mt-3 flex flex-wrap items-start gap-2">
        <OfficialPostLink url={OFFICIAL_GTA_VI_URL} label={ev.title} />
        <SaveButton saved={savedStore.has("event", ev.id)} onToggle={() => savedStore.toggle("event", ev.id)} label={ev.title} />
        <TrackGoalButton tracked={trackedStore.has("event", ev.id)} onToggle={() => trackedStore.toggle({ kind: "event", refId: ev.id, title: ev.title, date: ev.startsAt, url: OFFICIAL_GTA_VI_URL })} label={ev.title} />
      </div>
      {ev.canManage && (
        <section className="mt-4 rounded-xl border border-[var(--amber)] bg-[var(--surface2)] p-3" aria-label={`Leader controls for ${ev.title}`}>
          <p className="text-sm font-extrabold" style={{ color: "var(--amber)" }}>Leader controls</p>
          <p className="mt-1 text-xs leading-relaxed text-[var(--dim)]">You lead {ev.hostClanName || "the hosting crew"}, so this event is yours to run: edit anything about it, switch it between Public and Private, post its results, or remove it completely. Nobody else can do any of this.</p>
          {manageMsg && <p className="mt-2 text-sm font-semibold text-[var(--accent2)]" role="status">{manageMsg}</p>}
          <div className="mt-3 border-t border-[var(--border)] pt-3">
            <p className="text-sm font-extrabold">Event picture</p>
            <p className="mt-1 text-xs leading-relaxed text-[var(--dim)]">
              {ev.imageUrl
                ? "Your uploaded picture is the banner on this event's card — it replaced the theme picture. JPG or PNG, up to 4 MB, safety-checked automatically before it is stored."
                : `By default your card shows the ${ev.type} theme picture below — the picture follows the type you picked. Upload your own picture and it replaces the theme picture everywhere. JPG or PNG, up to 4 MB, safety-checked automatically before it is stored.`}
            </p>
            <img decoding="async" src={ev.imageUrl || eventArtForType(ev.type).img} alt={ev.imageUrl ? `Current picture for ${ev.title}` : eventArtForType(ev.type).alt} className="mt-2 h-28 w-full rounded-xl object-cover" loading="lazy" />
            <div className="mt-2 flex flex-wrap gap-2">
              <label className="btn-primary" style={{ minHeight: 40, padding: "6px 14px", fontSize: 13, display: "inline-flex", alignItems: "center", cursor: "pointer" }}>
                {setPic.isPending ? "Uploading…" : ev.imageUrl ? "Change picture" : "Upload a picture"}
                <input type="file" accept="image/jpeg,image/png" className="sr-only" aria-label={`Upload a picture for ${ev.title}`} onChange={(e) => { const f = e.target.files?.[0]; e.target.value = ""; if (f) { setPicMsg(""); setPic.mutate(f); } }} />
              </label>
              {ev.imageUrl && (
                <button type="button" className="btn-ghost" style={{ minHeight: 40, padding: "6px 14px", fontSize: 13 }} disabled={removePic.isPending} onClick={() => { setPicMsg(""); removePic.mutate(); }} aria-label={`Remove the picture from ${ev.title}`}>
                  Remove picture
                </button>
              )}
            </div>
            {picMsg && <p className="mt-2 text-sm font-semibold text-[var(--accent2)]" role="status">{picMsg}</p>}
          </div>
          <div className="mt-2 flex flex-wrap gap-2">
            <button type="button" className="btn-primary" style={{ minHeight: 40, padding: "6px 14px", fontSize: 13 }} onClick={() => { if (showEdit) setShowEdit(false); else openEdit(); }} aria-expanded={showEdit} aria-label={`${showEdit ? "Close" : "Open"} the editor for ${ev.title}`}>
              {showEdit ? "Close editor" : "Edit event"}
            </button>
            {!confirmRemove && (
              <button type="button" className="btn-ghost" style={{ minHeight: 40, padding: "6px 14px", fontSize: 13 }} onClick={() => setConfirmRemove(true)} aria-label={`Remove the event ${ev.title}`}>
                Remove event
              </button>
            )}
          </div>
          {confirmRemove && (
            <div className="mt-2 rounded-lg border border-[var(--accent)] p-3" role="alert">
              <p className="text-sm font-bold">Remove “{ev.title}” completely?</p>
              <p className="mt-1 text-xs text-[var(--dim)]">The event and everyone&apos;s RSVPs are deleted. This cannot be undone.</p>
              <div className="mt-2 flex flex-wrap gap-2">
                <button type="button" className="btn-primary" style={{ minHeight: 40, padding: "6px 14px", fontSize: 13 }} disabled={deleteEv.isPending} onClick={() => deleteEv.mutate()} aria-label={`Confirm removing the event ${ev.title}`}>
                  {deleteEv.isPending ? "Removing…" : "Yes, remove it"}
                </button>
                <button type="button" className="btn-ghost" style={{ minHeight: 40, padding: "6px 14px", fontSize: 13 }} onClick={() => setConfirmRemove(false)} aria-label="Keep the event">
                  Keep it
                </button>
              </div>
            </div>
          )}
          {showEdit && (
            <form
              className="mt-3 border-t border-[var(--border)] pt-3"
              onSubmit={(e) => {
                e.preventDefault();
                setError("");
                if (eTitle.trim().length < 4) { setError("Give the event a title (at least 4 characters)."); return; }
                if (!eStartsAt) { setError("Pick a date and time."); return; }
                updateEv.mutate();
              }}
            >
              <label className="flabel" htmlFor={`ev-edit-title-${ev.id}`}>Title</label>
              <input id={`ev-edit-title-${ev.id}`} className="field" {...FIELDS.updateEvent.title} value={eTitle} onChange={(e) => setETitle(e.target.value)} />
              <div className="grid gap-0 sm:grid-cols-2 sm:gap-x-4">
                <div>
                  <label className="flabel" htmlFor={`ev-edit-type-${ev.id}`}>Type</label>
                  <select id={`ev-edit-type-${ev.id}`} className="field" value={eType} onChange={(e) => setEType(e.target.value)}>
                    {EVENT_TYPES.map((t) => <option key={t}>{t}</option>)}
                  </select>
                </div>
                <div>
                  <label className="flabel" htmlFor={`ev-edit-plat-${ev.id}`}>Platform</label>
                  <select id={`ev-edit-plat-${ev.id}`} className="field" value={ePlat} onChange={(e) => setEPlat(e.target.value as typeof ePlat)}>
                    <option>Both</option><option>PS5</option><option>Xbox</option>
                  </select>
                </div>
                <div>
                  <label className="flabel" htmlFor={`ev-edit-when-${ev.id}`}>Date &amp; time</label>
                  <input id={`ev-edit-when-${ev.id}`} className="field" type="datetime-local" value={eStartsAt} onChange={(e) => setEStartsAt(e.target.value)} />
                </div>
                <div>
                  <label className="flabel" htmlFor={`ev-edit-tz-${ev.id}`}>Timezone (IANA)</label>
                  <input id={`ev-edit-tz-${ev.id}`} className="field" {...FIELDS.updateEvent.timezone} value={eTimezone} onChange={(e) => setETimezone(e.target.value)} />
                </div>
                <div>
                  <label className="flabel" htmlFor={`ev-edit-max-${ev.id}`}>Max players (max 32 — a full GTA lobby)</label>
                  <input id={`ev-edit-max-${ev.id}`} className="field" type="number" {...FIELDS.updateEvent.maxPlayers} value={eMax} onChange={(e) => setEMax(Number(e.target.value))} />
                </div>
                <div>
                  <label className="flabel" htmlFor={`ev-edit-prize-${ev.id}`}>Prize</label>
                  <input id={`ev-edit-prize-${ev.id}`} className="field" {...FIELDS.updateEvent.prize} value={ePrize} onChange={(e) => setEPrize(e.target.value)} />
                </div>
              </div>
              <span className="flabel" id={`ev-edit-vis-label-${ev.id}`}>Who can see and join it?</span>
              <div className="grid gap-2 sm:grid-cols-2" role="radiogroup" aria-labelledby={`ev-edit-vis-label-${ev.id}`}>
                <button type="button" role="radio" aria-checked={eVisibility === "Public"} className="picker-tile" style={{ textAlign: "left", minHeight: 72 }} onClick={() => setEVisibility("Public")}>
                  <span className="block font-extrabold">Public</span>
                  <span className="mt-0.5 block text-xs leading-relaxed text-[var(--dim)]">Listed for everyone — anyone can find it by name or hashtag and join.</span>
                </button>
                <button type="button" role="radio" aria-checked={eVisibility === "Private"} className="picker-tile" style={{ textAlign: "left", minHeight: 72 }} onClick={() => setEVisibility("Private")}>
                  <span className="block font-extrabold">Private — invite only</span>
                  <span className="mt-0.5 block text-xs leading-relaxed text-[var(--dim)]">Hidden from the list. Switching to Private creates a fresh invite code — any old code stops working.</span>
                </button>
              </div>
              <label className="flabel" htmlFor={`ev-edit-tags-${ev.id}`}>Hashtags</label>
              <input id={`ev-edit-tags-${ev.id}`} className="field" {...FIELDS.updateEvent.hashtags} value={eTags} onChange={(e) => setETags(e.target.value)} placeholder="#carmeet #nightdrive" />
              <label className="flabel" htmlFor={`ev-edit-desc-${ev.id}`}>Description</label>
              <textarea id={`ev-edit-desc-${ev.id}`} className="field" rows={3} {...FIELDS.updateEvent.description} value={eDesc} onChange={(e) => setEDesc(e.target.value)} />
              <label className="flabel" htmlFor={`ev-edit-rules-${ev.id}`}>Rules</label>
              <textarea id={`ev-edit-rules-${ev.id}`} className="field" rows={2} {...FIELDS.updateEvent.rules} value={eRules} onChange={(e) => setERules(e.target.value)} />
              <label className="flabel" htmlFor={`ev-edit-lobby-${ev.id}`}>Lobby details (only shown to players who RSVP Going)</label>
              <textarea id={`ev-edit-lobby-${ev.id}`} className="field" rows={2} {...FIELDS.updateEvent.lobbyDetails} value={eLobby} onChange={(e) => setELobby(e.target.value)} />
              <label className="flabel" htmlFor={`ev-edit-lobbylink-${ev.id}`}>Discord link or code (optional — only players who join can see it)</label>
              <input id={`ev-edit-lobbylink-${ev.id}`} className="field" {...FIELDS.updateEvent.lobbyLink} value={eLobbyLink} onChange={(e) => setELobbyLink(e.target.value)} />
              <button type="submit" className="btn-primary mt-3" disabled={updateEv.isPending} aria-label={`Save changes to ${ev.title}`}>
                {updateEv.isPending ? "Saving…" : `Save changes — make it ${eVisibility}`}
              </button>
            </form>
          )}
        </section>
      )}
      <button
        type="button"
        className="btn-ghost mt-3"
        onClick={() => setOpen(!open)}
        aria-label={`${open ? "Hide" : "Show"} attendees and results for ${ev.title}`}
      >
        {open ? "Hide attendees & results" : "Attendees & results"}
      </button>
      {open && (
        <div className="mt-3 border-t border-[var(--border)] pt-3">
          {attendees.isPending && <p className="text-sm text-[var(--dim)]">Loading attendees…</p>}
          {attendees.data && attendees.data.items.length === 0 && (
            <p className="text-sm text-[var(--dim)]">No RSVPs yet — be the first.</p>
          )}
          <ul className="grid gap-1.5 text-sm">
            {attendees.data?.items.map((a) => (
              <li key={a.playerKey} className="flex flex-wrap items-center gap-2">
                <span className="min-w-0 flex-1 truncate">· {a.gamertag} — <span className="text-[var(--dim)]">{a.status}</span></span>
                {ev.canManage && a.playerKey !== playerKey && a.gamertag.toLowerCase() !== ev.host.toLowerCase() && (
                  <button type="button" className="btn-ghost flex-none" style={{ minHeight: 32, padding: "3px 10px", fontSize: 12 }} disabled={removeAttendee.isPending} onClick={() => removeAttendee.mutate(a.playerKey)} aria-label={`Remove ${a.gamertag} from ${ev.title} — they leave the event and its chat, and cannot rejoin`}>
                    Remove
                  </button>
                )}
              </li>
            ))}
          </ul>
          {ev.canManage && attendees.data && attendees.data.items.length > 0 && (
            <p className="mt-1.5 text-xs leading-relaxed text-[var(--dim)]">Removing someone takes them off this event and out of its event chat in Messages, and they can&apos;t rejoin this event.</p>
          )}
          {(isHost || ev.canManage) && (
            <div className="mt-2 rounded-xl border border-[var(--border)] bg-[var(--surface2)] p-3">
              <p className="text-sm font-bold">Leader: confirm the result in one tap</p>
              <p className="mt-1 text-sm leading-relaxed text-[var(--dim)]">Pick the top 3 from the players who RSVP&apos;d. They earn +50 / +30 / +20 Rank Points automatically — attendance (+15) was already counted from each RSVP. Event Rewards: the winners&apos; crews also get Vice Credits in the crew wallet (150 / 75 / 50), and every other crew that showed up gets +10 participation credits. No proof uploads, no per-player forms.</p>
              <div className="mt-2 grid gap-2 sm:grid-cols-3">
                {([["1st place", first, setFirst], ["2nd place", second, setSecond], ["3rd place", third, setThird]] as const).map(([label, val, setter]) => (
                  <div key={label}>
                    <label className="flabel" htmlFor={`ev-${label}-${ev.id}`}>{label}</label>
                    <select id={`ev-${label}-${ev.id}`} className="field" value={val} onChange={(e) => setter(e.target.value)} aria-label={`${label} finisher for ${ev.title}`}>
                      <option value="">—</option>
                      {(attendees.data?.items ?? []).filter((a) => a.status === "Going").map((a) => (
                        <option key={a.gamertag} value={a.gamertag}>{a.gamertag}</option>
                      ))}
                    </select>
                  </div>
                ))}
              </div>
              <button type="button" className="btn-primary mt-3" disabled={hostConfirm.isPending || (!first && !second && !third)} onClick={() => { setHostMsg(""); hostConfirm.mutate(); }}>
                {hostConfirm.isPending ? "Confirming…" : "Confirm results & pay rewards"}
              </button>
              {hostMsg && <p className="mt-2 text-sm font-semibold text-[var(--accent2)]" role="status">{hostMsg}</p>}
            </div>
          )}
          {ev.canManage ? (
            <>
              <label className="flabel" htmlFor={`ev-results-${ev.id}`}>Post results / leaderboard</label>
              <textarea id={`ev-results-${ev.id}`} className="field" rows={3} {...FIELDS.setEventResults.results} value={resultsDraft} onChange={(e) => setResultsDraft(e.target.value)} placeholder={"1. gamertag — 1:58.2\n2. …"} />
              <button
                type="button"
                className="btn-primary mt-2"
                disabled={saveResults.isPending || !resultsDraft.trim()}
                onClick={() => saveResults.mutate()}
              >
                Save results
              </button>
            </>
          ) : (
            <p className="mt-2 text-xs leading-relaxed text-[var(--dim)]">Results are posted by the hosting crew&apos;s Leader — only they control this event.</p>
          )}
          <p className="mt-3 text-xs leading-relaxed text-[var(--dim)]">After the event, share photos and clips from it in the Community Feed — post them as Gameplay or Car Meet so the whole community can see them, and the host&apos;s confirmed results pay Rank Points to the winners.</p>
        </div>
      )}
      </div>
    </article>
  );
}

function EventsView({
  playerKey,
  gamertag,
  go,
  savedStore,
  trackedStore,
}: {
  playerKey: string;
  gamertag: string;
  go: (t: Tab) => void;
  savedStore: ReturnType<typeof useSaved>;
  trackedStore: ReturnType<typeof useTrackedGoals>;
}) {
  const qc = useQueryClient();
  // Discovery state: find events by name OR by hashtag — both ways work.
  const [search, setSearch] = useState("");
  const [tag, setTag] = useState("");
  const [typeFilter, setTypeFilter] = useState("All");
  const [platformFilter, setPlatformFilter] = useState("All");
  const [visibilityFilter, setVisibilityFilter] = useState<"All" | "Public" | "Private">("All");
  // Create form state.
  const [showForm, setShowForm] = useState(false);
  const [clanId, setClanId] = useState(0);
  const [title, setTitle] = useState("");
  const [type, setType] = useState("Car Meet");
  const [visibility, setVisibility] = useState<"Public" | "Private">("Public");
  const [hashtags, setHashtags] = useState("");
  const [startsAt, setStartsAt] = useState("");
  const [timezone, setTimezone] = useState("America/New_York");
  const [plat, setPlat] = useState<"PS5" | "Xbox" | "Both">("Both");
  const [maxPlayers, setMaxPlayers] = useState(16);
  const [description, setDescription] = useState("");
  const [rules, setRules] = useState("");
  const [prize, setPrize] = useState("Bragging rights + site badge");
  const [lobbyDetails, setLobbyDetails] = useState("");
  const [lobbyLink, setLobbyLink] = useState("");
  // Simple-by-default create form (owner's direction): only the
  // essentials show; everything else lives under "More options".
  // payExtra is the 200-Vice-Credit extra event past the weekly limit.
  const [showMoreOptions, setShowMoreOptions] = useState(false);
  const [payExtra, setPayExtra] = useState(false);
  const [error, setError] = useState("");
  const [createdMsg, setCreatedMsg] = useState("");
  // Invite-code join state.
  const [inviteInput, setInviteInput] = useState("");
  const [inviteMsg, setInviteMsg] = useState("");
  const [foundEvent, setFoundEvent] = useState<EventItemT | null>(null);

  const allEvents = useQuery({
    queryKey: ["events", playerKey, "all"],
    queryFn: () => api.listEvents({ playerKey }),
  });
  const events = useQuery({
    queryKey: ["events", playerKey, search, tag, typeFilter, platformFilter, visibilityFilter],
    queryFn: () => api.listEvents({ playerKey, search, hashtag: tag, typeFilter, platformFilter, visibilityFilter }),
  });
  const hosting = useQuery({
    queryKey: ["eventHosting", playerKey],
    queryFn: () => api.getMyEventHosting({ playerKey }),
  });
  const eligibleClans = (hosting.data?.items ?? []).filter((i) => i.eligible);
  const canHost = eligibleClans.length > 0;
  const activeClanId = eligibleClans.some((c) => c.clanId === clanId) ? clanId : (eligibleClans[0]?.clanId ?? 0);
  // Weekly limit status (one community event per Leader per week,
  // on top of the Leader + 10-member rules): drives the clear note
  // on the Create Event form, the blocked notice with the exact
  // next-available date, and the disabled submit.
  const creationStatus = useQuery({
    queryKey: ["eventCreationStatus", playerKey],
    queryFn: () => api.getEventCreationStatus({ playerKey }),
    enabled: canHost,
  });
  const weeklyBlocked = Boolean(creationStatus.data?.isLeader && !creationStatus.data.canCreate);
  const fmtEventDate = (iso: string) => new Date(iso).toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric", year: "numeric" });

  const invalidate = () => {
    qc.invalidateQueries({ queryKey: ["events"] });
    qc.invalidateQueries({ queryKey: ["eventHosting"] });
    qc.invalidateQueries({ queryKey: ["eventCreationStatus"] });
    qc.invalidateQueries({ queryKey: ["wallet"] });
    qc.invalidateQueries({ queryKey: ["profile"] });
  };
  const create = useMutation({
    mutationFn: async () =>
      await api.createEvent({
        playerKey, gamertag, clanId: activeClanId,
        title, type, startsAt, timezone, platform: plat, maxPlayers,
        description, rules, prize, visibility, hashtags, lobbyDetails, lobbyLink,
        useCredits: payExtra && weeklyBlocked,
      }),
    onSuccess: (_res, _vars) => {
      setCreatedMsg(visibility === "Private"
        ? "Private event created. It is hidden from the public list — open the event below to find its invite code and invite link, and share them with the people you want there. Your crew's members can already see it."
        : "Public event created — it is now on the discovery list below for everyone to find by name or hashtag.");
      setTitle(""); setStartsAt(""); setDescription(""); setRules(""); setHashtags("");
      setPayExtra(false);
      setShowForm(false); setError(""); invalidate();
    },
    onError: (e) => setError(e.message),
  });
  const lookupInvite = useMutation({
    mutationFn: async (code: string) => await api.getEventByInviteCode({ playerKey, code }),
    onSuccess: (res) => {
      if (res.item) {
        setFoundEvent(res.item);
        setInviteMsg(`Found it — "${res.item.title}", hosted by ${res.item.hostClanName || res.item.host}. RSVP below to join.`);
      } else {
        setFoundEvent(null);
        setInviteMsg("No event matches that invite code. Check the code and try again — codes are 6 letters/numbers, like K7PX2A.");
      }
    },
    onError: (e) => setInviteMsg(e.message),
  });

  // An invite link (#event=CODE) opened in ViceSunshine lands here: the
  // app shell stored the code on this device — look the event up once.
  useEffect(() => {
    try {
      const code = window.localStorage.getItem("vv-event-invite");
      if (code) {
        window.localStorage.removeItem("vv-event-invite");
        setInviteInput(code);
        lookupInvite.mutate(code);
      }
    } catch { /* storage unavailable */ }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Hashtag chips are built from the events that actually exist, so
  // every chip leads somewhere. Popular tags come first.
  const tagCounts = new Map<string, number>();
  for (const ev of allEvents.data?.items ?? []) {
    for (const t of ev.hashtags) tagCounts.set(t, (tagCounts.get(t) ?? 0) + 1);
  }
  const chips = [...tagCounts.entries()]
    .sort((a, b) => {
      const pa = POPULAR_EVENT_TAGS.indexOf(a[0]);
      const pb = POPULAR_EVENT_TAGS.indexOf(b[0]);
      const ra = pa === -1 ? 99 : pa;
      const rb = pb === -1 ? 99 : pb;
      return ra - rb || b[1] - a[1];
    })
    .slice(0, 10);
  const filtersActive = Boolean(search.trim() || tag || typeFilter !== "All" || platformFilter !== "All" || visibilityFilter !== "All");
  const clearFilters = () => { setSearch(""); setTag(""); setTypeFilter("All"); setPlatformFilter("All"); setVisibilityFilter("All"); };
  const pickTag = (t: string) => { setTag(t); setSearch(""); };

  return (
    <div className="events-view">
      <SectionBanner src={secEventsUrl} alt="Original ViceSunshine illustration of a car meet at dusk with rows of colourful muscle cars" />
      <SectionTitle sub="Car meets, races, time trials, screenshot contests and crew events — hosted by crew Leaders whose crew has 10 or more members. Find one by name or by hashtag, and RSVP to join. Public events are open to everyone; private events are invite-only. Voice chat and lobbies happen on the ViceSunshine Discord server — find the invite in the Discord tab under Community.">
        Community Events
      </SectionTitle>
      {!gamertag && (
        <p className="mb-4 rounded-lg border border-[var(--amber)] p-3 text-sm text-[var(--amber)]">
          Set your gamertag to RSVP or host.{" "}
          <button type="button" className="font-bold underline" onClick={() => go("profile")}>Set up your profile →</button>
        </p>
      )}

      {/* ---- How Community Events work ---- */}
      <section className="card mb-4 p-4" aria-label="How Community Events work">
        <div className="rounded-xl bg-[var(--surface2)] p-3">
          <p className="text-sm font-extrabold">Community Events — crew-hosted</p>
          <p className="mt-1 text-sm leading-relaxed text-[var(--dim)]">Big, planned meetups. An event can <strong className="text-[var(--text)]">only</strong> be created by a player who is <strong className="text-[var(--text)]">in a crew</strong>, is that crew&apos;s <strong className="text-[var(--text)]">Leader</strong>, and whose crew has <strong className="text-[var(--text)]">at least 10 members</strong>. That Leader controls the event: they can edit it, make it Public or Private, post results, or remove it. Everyone else just finds one they like and joins.</p>
        </div>
      </section>

      {/* ---- Discovery: search by name or hashtag + filters ---- */}
      <section className="card mb-4 p-4" aria-label="Find events">
        <label className="flabel" htmlFor="ev-search">Search by name or #hashtag</label>
        <input
          id="ev-search"
          className="field"
          {...FIELDS.listEvents.search}
          value={search}
          onChange={(e) => { setSearch(e.target.value); if (e.target.value.trim()) setTag(""); }}
          placeholder="Event name, host crew… or #carmeet, #race, #timetrial"
          aria-label="Search events by name or hashtag"
        />
        <div className="mt-3 flex flex-wrap gap-1.5" role="group" aria-label="Browse by hashtag">
          <button type="button" className="chip" aria-pressed={!tag && !search.trim()} onClick={clearFilters}>All events</button>
          {chips.map(([t, n]) => (
            <button key={t} type="button" className="chip" aria-pressed={tag === t} onClick={() => pickTag(tag === t ? "" : t)} aria-label={`Events tagged #${t}, ${n} event${n === 1 ? "" : "s"}`}>
              #{t} · {n}
            </button>
          ))}
        </div>
        <div className="mt-3 grid gap-3 sm:grid-cols-3">
          <div>
            <label className="flabel" htmlFor="ev-typefilter">Type</label>
            <select id="ev-typefilter" className="field" value={typeFilter} onChange={(e) => setTypeFilter(e.target.value)} aria-label="Filter by event type">
              <option value="All">All types</option>
              {EVENT_TYPES.map((t) => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>
          <div>
            <label className="flabel" htmlFor="ev-platfilter">Platform</label>
            <select id="ev-platfilter" className="field" value={platformFilter} onChange={(e) => setPlatformFilter(e.target.value)} aria-label="Filter by platform">
              <option value="All">All platforms</option>
              <option value="PS5">PS5</option>
              <option value="Xbox">Xbox</option>
              <option value="Both">Both</option>
            </select>
          </div>
          <div>
            <span className="flabel" id="ev-visfilter-label">Who can join</span>
            <div className="flex gap-1.5" role="group" aria-labelledby="ev-visfilter-label">
              {(["All", "Public", "Private"] as const).map((v) => (
                <button key={v} type="button" className="chip flex-1" aria-pressed={visibilityFilter === v} onClick={() => setVisibilityFilter(v)} aria-label={`Show ${v === "All" ? "all" : v.toLowerCase()} events`}>
                  {v}
                </button>
              ))}
            </div>
          </div>
        </div>
        <p className="mt-3 text-sm text-[var(--dim)]" role="status">
          {events.isPending ? "Loading events…" : `${events.data?.items.length ?? 0} event${(events.data?.items.length ?? 0) === 1 ? "" : "s"} found${tag ? ` for #${tag}` : ""}${search.trim() ? ` matching "${search.trim()}"` : ""}.`}
          {filtersActive && <> <button type="button" className="font-bold text-[var(--accent2)] underline" onClick={clearFilters}>Clear search &amp; filters</button></>}
        </p>
      </section>

      {/* ---- Join a private event with an invite code / link ---- */}
      <section className="card mb-4 p-4" aria-label="Join a private event with an invite code">
        <h3 className="text-base font-extrabold tracking-tight">Joining a private event?</h3>
        <p className="mt-1 text-sm leading-relaxed text-[var(--dim)]">Private events don&apos;t appear in the public list. If a host sent you an invite link, open it and the event appears here automatically. Or enter the invite code they gave you:</p>
        <form
          className="mt-3 flex flex-wrap gap-2"
          onSubmit={(e) => {
            e.preventDefault();
            const code = inviteInput.trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
            if (code.length < 4) { setInviteMsg("Enter the 6-character invite code from your invite link."); setFoundEvent(null); return; }
            setInviteMsg("");
            lookupInvite.mutate(code);
          }}
        >
          <label className="sr-only" htmlFor="ev-invite-code">Private event invite code</label>
          <input
            id="ev-invite-code"
            className="field font-mono uppercase tracking-[0.2em]"
            style={{ maxWidth: 220 }}
            value={inviteInput}
            onChange={(e) => setInviteInput(e.target.value)}
            placeholder="K7PX2A"
            maxLength={12}
            autoComplete="off"
          />
          <button type="submit" className="btn-primary" disabled={lookupInvite.isPending} aria-label="Find the private event for this invite code">
            {lookupInvite.isPending ? "Looking…" : "Find event"}
          </button>
        </form>
        {inviteMsg && <p className="mt-2 text-sm font-semibold text-[var(--accent2)]" role="status">{inviteMsg}</p>}
        {foundEvent && (
          <div className="mt-3">
            <EventCard ev={foundEvent} playerKey={playerKey} gamertag={gamertag} onTag={pickTag} savedStore={savedStore} trackedStore={trackedStore} />
          </div>
        )}
      </section>

      {/* ---- Create: Leader of a 10+ member clan only ---- */}
      {canHost ? (
        <>
          <button type="button" className="btn-primary mb-4" onClick={() => setShowForm(!showForm)} aria-expanded={showForm}>+ Create a Community Event</button>
          <p className="mb-3 text-[13px] leading-relaxed text-[var(--dim)]">
            <strong className="text-[var(--text)]">Weekly limit:</strong> each crew Leader can create <strong className="text-[var(--text)]">one free community event per week</strong> (you must be the crew Leader, and your crew needs at least 10 members). Need another one sooner? An extra event costs <strong className="text-[var(--text)]">200 Vice Credits</strong> — the credits you earn from referrals and levelling up.
          </p>
          {weeklyBlocked && creationStatus.data && (
            <div className="mb-3 rounded-lg border border-[var(--amber)] p-3 text-sm leading-relaxed" role="status">
              <p>
                You created &ldquo;{creationStatus.data.lastTitle}&rdquo; on {fmtEventDate(creationStatus.data.lastCreatedAt)} — that was this week&apos;s free event. Your next free event opens <strong>{fmtEventDate(creationStatus.data.nextAvailableAt)}</strong>.
              </p>
              <p className="mt-2">
                Or start an extra event right now for <strong>{creationStatus.data.extraEventCost} Vice Credits</strong>. Your balance: <strong>{creationStatus.data.creditBalance.toLocaleString()} VC</strong>.
              </p>
              {creationStatus.data.canAffordExtra ? (
                <label className="mt-2.5 flex cursor-pointer items-center gap-2.5 font-bold text-[var(--text)]">
                  <input type="checkbox" checked={payExtra} onChange={(e) => setPayExtra(e.target.checked)} aria-label={`Start this extra event for ${creationStatus.data.extraEventCost} Vice Credits`} style={{ width: 20, height: 20, accentColor: "var(--accent)" }} />
                  Start this extra event for {creationStatus.data.extraEventCost} Vice Credits
                </label>
              ) : (
                <p className="mt-2 text-[var(--dim)]">You don&apos;t have {creationStatus.data.extraEventCost} Vice Credits yet — referring a friend earns you 200 VC and 15 XP, and levelling up pays credits too.</p>
              )}
            </div>
          )}
          {createdMsg && <p className="mb-3 rounded-lg border border-[var(--accent2)] p-3 text-sm font-semibold text-[var(--accent2)]" role="status">{createdMsg}</p>}
          {error && <p className="mb-3 text-sm text-[var(--amber)]" role="alert">{error}</p>}
          {showForm && (
            <form
              className="card mb-4 p-4"
              onSubmit={(e) => {
                e.preventDefault();
                setError("");
                if (!gamertag) { setError("Set your gamertag first — it becomes the event host name."); return; }
                if (title.trim().length < 4) { setError("Give the event a title (at least 4 characters)."); return; }
                if (!startsAt) { setError("Pick a date and time."); return; }
                if (!activeClanId) { setError("You need a crew you lead with at least 10 members to create an event."); return; }
                create.mutate();
              }}
            >
              <p className="text-sm leading-relaxed text-[var(--dim)]">You are creating this event as the Leader of <strong className="text-[var(--text)]">{eligibleClans.find((c) => c.clanId === activeClanId)?.clanName}</strong>. Private events get an invite code and invite link automatically, so you can invite players from outside your crew too.</p>
              {eligibleClans.length > 1 && (
                <div className="mt-2">
                  <label className="flabel" htmlFor="ev-clan">Host crew</label>
                  <select id="ev-clan" className="field" value={activeClanId} onChange={(e) => setClanId(Number(e.target.value))} aria-label="Crew hosting this event">
                    {eligibleClans.map((c) => <option key={c.clanId} value={c.clanId}>[{c.clanTag}] {c.clanName} · {c.memberCount} members</option>)}
                  </select>
                </div>
              )}
              <label className="flabel" htmlFor="ev-title">Title</label>
              <input id="ev-title" className="field" {...FIELDS.createEvent.title} value={title} onChange={(e) => setTitle(e.target.value)} placeholder="Friday Night Car Meet — Ocean Drive" />
              <div className="grid gap-0 sm:grid-cols-2 sm:gap-x-4">
                <div>
                  <label className="flabel" htmlFor="ev-type">Type</label>
                  <select id="ev-type" className="field" value={type} onChange={(e) => setType(e.target.value)}>
                    {EVENT_TYPES.map((t) => <option key={t}>{t}</option>)}
                  </select>
                </div>
                <div className="sm:col-span-2">
                  <img decoding="async" src={eventArtForType(type).img} alt={eventArtForType(type).alt} className="h-28 w-full rounded-xl object-cover" loading="lazy" />
                  <p className="mt-1.5 text-xs leading-relaxed text-[var(--dim)]">Your event&apos;s picture follows its type — this {type} artwork is what your card shows by default. After creating the event, you can upload your own picture from the event card and it replaces this theme picture.</p>
                </div>
                <div>
                  <label className="flabel" htmlFor="ev-plat">Platform</label>
                  <select id="ev-plat" className="field" value={plat} onChange={(e) => setPlat(e.target.value as typeof plat)}>
                    <option>Both</option><option>PS5</option><option>Xbox</option>
                  </select>
                </div>
                <div>
                  <label className="flabel" htmlFor="ev-when">Date &amp; time</label>
                  <input id="ev-when" className="field" type="datetime-local" value={startsAt} onChange={(e) => setStartsAt(e.target.value)} />
                </div>
              </div>
              <span className="flabel" id="ev-vis-label">Who can see and join it?</span>
              <div className="grid gap-2 sm:grid-cols-2" role="radiogroup" aria-labelledby="ev-vis-label">
                <button type="button" role="radio" aria-checked={visibility === "Public"} className="picker-tile" style={{ textAlign: "left", minHeight: 72 }} onClick={() => setVisibility("Public")}>
                  <span className="block font-extrabold">Public</span>
                  <span className="mt-0.5 block text-xs leading-relaxed text-[var(--dim)]">Listed for everyone — anyone can find it by name or hashtag and join.</span>
                </button>
                <button type="button" role="radio" aria-checked={visibility === "Private"} className="picker-tile" style={{ textAlign: "left", minHeight: 72 }} onClick={() => setVisibility("Private")}>
                  <span className="block font-extrabold">Private — invite only</span>
                  <span className="mt-0.5 block text-xs leading-relaxed text-[var(--dim)]">Hidden from the list. Your crew sees it; everyone else needs your invite link or invite code.</span>
                </button>
              </div>
              {/* Everything past the essentials is optional and
                  folded away (owner's direction: creating an event
                  must feel simple — a title, a type, a time, who can
                  join, done). Private events get their invite code
                  and link automatically — nothing to type. */}
              <button type="button" className="btn-ghost mt-4" style={{ minHeight: 40, padding: "6px 14px", fontSize: 13 }} onClick={() => setShowMoreOptions(!showMoreOptions)} aria-expanded={showMoreOptions} aria-label="Toggle more event options — description, rules, hashtags, lobby details">
                {showMoreOptions ? "Hide more options" : "More options — description, rules, hashtags, lobby…"}
              </button>
              {showMoreOptions && (
                <div>
                  <div className="grid gap-0 sm:grid-cols-3 sm:gap-x-4">
                    <div>
                      <label className="flabel" htmlFor="ev-tz">Timezone (IANA)</label>
                      <input id="ev-tz" className="field" {...FIELDS.createEvent.timezone} value={timezone} onChange={(e) => setTimezone(e.target.value)} placeholder="America/Toronto" />
                    </div>
                    <div>
                      <label className="flabel" htmlFor="ev-max">Max players (max 32 — a full GTA lobby)</label>
                      <input id="ev-max" className="field" type="number" {...FIELDS.createEvent.maxPlayers} value={maxPlayers} onChange={(e) => setMaxPlayers(Number(e.target.value))} />
                    </div>
                    <div>
                      <label className="flabel" htmlFor="ev-prize">Prize</label>
                      <input id="ev-prize" className="field" {...FIELDS.createEvent.prize} value={prize} onChange={(e) => setPrize(e.target.value)} />
                    </div>
                  </div>
                  <label className="flabel" htmlFor="ev-tags">Hashtags (so players find it by what they like)</label>
                  <input id="ev-tags" className="field" {...FIELDS.createEvent.hashtags} value={hashtags} onChange={(e) => setHashtags(e.target.value)} placeholder="#carmeet #nightdrive #cleanbuilds" />
                  <p className="mt-1 text-xs text-[var(--dim)]">Your event type adds its own tags automatically — a Car Meet is always findable as #carmeet, a Race as #race, a Time Trial as #timetrial.</p>
                  <label className="flabel" htmlFor="ev-desc">Description</label>
                  <textarea id="ev-desc" className="field" rows={3} {...FIELDS.createEvent.description} value={description} onChange={(e) => setDescription(e.target.value)} />
                  <label className="flabel" htmlFor="ev-rules">Rules</label>
                  <textarea id="ev-rules" className="field" rows={2} {...FIELDS.createEvent.rules} value={rules} onChange={(e) => setRules(e.target.value)} />
                  <label className="flabel" htmlFor="ev-lobby">Lobby details (only shown to players who RSVP Going)</label>
                  <textarea id="ev-lobby" className="field" rows={2} {...FIELDS.createEvent.lobbyDetails} value={lobbyDetails} onChange={(e) => setLobbyDetails(e.target.value)} placeholder="Your PSN / Xbox gamertag, the meet point, and how to join the same lobby" />
                  <label className="flabel" htmlFor="ev-lobbylink">Discord link or code (optional — only players who join can see it)</label>
                  <input id="ev-lobbylink" className="field" {...FIELDS.createEvent.lobbyLink} value={lobbyLink} onChange={(e) => setLobbyLink(e.target.value)} placeholder="https://discord.gg/…" />
                </div>
              )}
              <p className="mt-2 text-xs text-[var(--dim)]">Prizes are bragging rights and site badges — no real-money prizes. Private events get an invite code and invite link automatically. Lobby details are shared by the host, only for RSVP&apos;d players — never shown publicly.</p>
              <button type="submit" className="btn-primary mt-3" disabled={create.isPending || (weeklyBlocked && !payExtra)}>
                {create.isPending ? "Creating…" : weeklyBlocked && !payExtra ? "Weekly limit reached — tick the extra event above" : weeklyBlocked && payExtra ? `Create extra ${visibility.toLowerCase()} event — 200 Vice Credits` : `Create ${visibility.toLowerCase()} community event`}
              </button>
            </form>
          )}
        </>
      ) : (
        <section className="card mb-4 p-4" aria-label="Who can create events">
          <h3 className="text-base font-extrabold tracking-tight">Creating events is for crew Leaders</h3>
          <p className="mt-1 text-sm leading-relaxed text-[var(--dim)]">Only the Leader of a crew with at least 10 members can create Community Events — that keeps the list full of real, hosted events. Each Leader can create one event per week. Everyone can browse, search and join them.</p>
          {hosting.isPending && <p className="mt-2 text-sm text-[var(--dim)]">Checking your crews…</p>}
          {hosting.data && hosting.data.items.length === 0 && (
            <p className="mt-2 text-sm text-[var(--dim)]">You are not in a crew yet. Join one — or found your own, grow it to 10 members, and you can start hosting.{" "}
              <button type="button" className="font-bold text-[var(--accent2)] underline" onClick={() => go("clans")}>Browse crews</button>
            </p>
          )}
          {hosting.data && hosting.data.items.length > 0 && (
            <ul className="mt-2 grid gap-1.5">
              {hosting.data.items.map((i) => (
                <li key={i.clanId} className="rounded-lg bg-[var(--surface2)] px-3 py-2 text-sm">
                  <strong>{i.clanName}</strong> <span className="text-[var(--dim)]">· {i.memberCount} member{i.memberCount === 1 ? "" : "s"} · you are {i.myRole}</span>
                  <span className="block text-xs text-[var(--dim)]">{i.reason}</span>
                </li>
              ))}
            </ul>
          )}
        </section>
      )}

      {/* ---- The big discovery list ---- */}
      {events.isPending && <p className="text-sm text-[var(--dim)]">Loading events…</p>}
      {events.data && events.data.items.length === 0 && !filtersActive && (
        <EmptyNote>No events scheduled yet. The first crew Leader with 10 members can host the first launch-week meetup, time trial or screenshot contest.</EmptyNote>
      )}
      {events.data && events.data.items.length === 0 && filtersActive && (
        <EmptyNote>No events match that search. Try a different name, or tap a hashtag like #carmeet or #race above.</EmptyNote>
      )}
      <div className="grid gap-4 md:grid-cols-2">
        {events.data?.items.map((ev) => (
          <EventCard key={ev.id} ev={ev} playerKey={playerKey} gamertag={gamertag} onTag={pickTag} savedStore={savedStore} trackedStore={trackedStore} />
        ))}
      </div>
    </div>
  );
}

