/* No FEED_TABS filter list any more (owner's direction): the Feed
   has no category chooser — categories are picked when posting. */
type FeedPost = ApiResponse<typeof api, "listFeed">["items"][number];

function detectedCurrency(): string {
  try {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || "";
    if (tz.startsWith("America/Toronto") || tz.startsWith("America/Vancouver") || tz.startsWith("America/Winnipeg") || tz.startsWith("America/Halifax") || tz.startsWith("America/St_Johns") || tz.startsWith("America/Edmonton") || tz.startsWith("America/Montreal")) return "CAD";
    if (tz === "Europe/London") return "GBP";
    if (tz.startsWith("Europe/")) return "EUR";
    if (tz.startsWith("Australia/") || tz.startsWith("Pacific/Auckland")) return "AUD";
    if (tz.startsWith("America/")) return "USD";
  } catch { /* fall through */ }
  return "CAD";
}

// Premium pricing is LOCATION-BASED (owner's decision, Nov 21,
// 2026): the ORIGINAL price is $4.99 USD and every other currency
// converts from it. The visitor's currency is their Settings
// currency when they picked one, otherwise the auto-detected one
// above. Conversion uses a deliberately HIGH rate (units of local
// currency per 1 USD, above typical market rates) and rounds UP to
// a clean .99 price point, so a local Premium price is never worth
// less than $4.99 USD — e.g. the straight conversion for Canada
// lands near CA$7.09 and the shown price is CA$7.99. The server
// carries an identical copy of this table (actions.ts FX_FROM_USD)
// so every surface — banner, Premium page, Settings, Owner
// Dashboard, Ask Vice, checkout — shows the same amount for the
// same visitor; keep the two in sync. A currency with no entry
// falls back to the $4.99 USD price, the same fallback checkout
// uses when Stripe has no price for a currency.
const PREMIUM_PRICE_USD = 4.99;
const FX_FROM_USD: Record<string, { rate: number; symbol: string }> = {
  CAD: { rate: 1.42, symbol: "CA$" },
  EUR: { rate: 0.95, symbol: "€" },
  GBP: { rate: 0.82, symbol: "£" },
  AUD: { rate: 1.55, symbol: "A$" },
};
function roundUpToCleanPrice(amount: number): number {
  let candidate = Math.floor(amount) + 0.99;
  if (candidate < amount + 0.05) candidate += 1;
  return Math.round(candidate * 100) / 100;
}
function premiumPriceFor(currency: string): { code: string; amount: number; label: string } {
  const code = (currency || "").trim().toUpperCase();
  const fx = FX_FROM_USD[code];
  if (!fx) return { code: "USD", amount: PREMIUM_PRICE_USD, label: `$${PREMIUM_PRICE_USD.toFixed(2)}` };
  const amount = roundUpToCleanPrice(PREMIUM_PRICE_USD * fx.rate);
  return { code, amount, label: `${fx.symbol}${amount.toFixed(2)}` };
}
function premiumPriceLabel(currency: string): string {
  return premiumPriceFor(currency).label;
}
// Plain conversion for money figures that are not a price point
// (e.g. revenue): same high-rate table, no .99 rounding.
function moneyFromUsd(amountUsd: number, currency: string): string {
  const code = (currency || "").trim().toUpperCase();
  const fx = FX_FROM_USD[code];
  if (!fx) return `$${amountUsd.toFixed(2)}`;
  return `${fx.symbol}${(amountUsd * fx.rate).toFixed(2)}`;
}
function useDisplayCurrency(playerKey: string): string {
  const settings = useQuery({
    queryKey: ["settings", playerKey],
    queryFn: () => api.getSettings({ playerKey }),
    enabled: Boolean(playerKey),
    staleTime: 60_000,
  });
  return settings.data?.currency || detectedCurrency();
}

function SettingsToggle({ label, hint, checked, onChange }: { label: string; hint?: string; checked: boolean; onChange: (v: boolean) => void }) {
  return (
    <label className="flex cursor-pointer items-start justify-between gap-4 py-3">
      <span>
        <span className="block text-sm font-bold">{label}</span>
        {hint && <span className="mt-0.5 block text-[13px] leading-relaxed text-[var(--dim)]">{hint}</span>}
      </span>
      <input
        type="checkbox"
        className="mt-1 h-6 w-6 flex-none accent-[#ff2e88]"
        checked={checked}
        onChange={(e) => onChange(e.target.checked)}
        aria-label={label}
      />
    </label>
  );
}

// ---- Settings: Muse's Settings, replicated exactly (owner's
// direction, from Ben's screenshots of Muse's own shell) with only
// the colours changed to the ViceSunshine theme. The flow is Muse's
// three layers: (1) the sidebar's bottom left carries ONLY a
// two-line account trigger; (2) pressing it opens a small popover
// box anchored bottom-left (profile / Wallet / Premium / Report an
// issue, a divider, then Settings with its ⌘, hint); (3) pressing
// Settings in that box opens this centred modal — 880px wide, 24px
// radius, a darker 248px left nav of 40px icon rows (selected row
// filled lighter with a HOT-PINK outline where Muse uses blue,
// Log out pinned at the bottom) and a right detail panel with a
// 17px title, an X in a small circle, dim 13px section labels, and
// content on 16px-radius cards one step lighter than the panel.
// General mirrors Muse's General panel in order: the ViceSunshine
// Account card (avatar mark, "Password, security, personal
// details", ↗ top-right), the Plan section in Muse's Usage-card
// layout (plan name left, status right, sub line, divider, Upgrade
// link in pink), Redeem invite code (gift icon, chevron), Refer a
// Friend, the single-line Language row (value + chevron, controls
// open underneath), then Appearance with the Mode card (sun / moon
// / monitor segmented pill, accent colour dots under a divider).
// There is deliberately NO percentage / usage tracking like Muse's
// "61% used" bar: ViceSunshine has no usage meter, so the Plan cards
// carry the honest status / price on the right instead. Wallet holds the
// saved payment methods (Stripe: brand + last 4 + expiry only, never
// a full card number) used for the one-tap Premium subscribe button.
// Crew cosmetics are FREE in Crew Settings → Crew customisation
// (crew owner only) and equipped there; profiles have no
// cosmetics. Settings does not duplicate any of it.
/* Comment history (owner's direction): comments never show on
   the profile — they live here, in Settings → Data controls.
   Every comment the player has written on a Feed post, newest
   first, with the post it was written on. Backed by
   listMyFeedComments (real stored rows only). */
function CommentHistoryCard({ playerKey }: { playerKey: string }) {
  const [open, setOpen] = useState(false);
  const history = useQuery({
    queryKey: ["my-feed-comments", playerKey],
    queryFn: () => api.listMyFeedComments({ playerKey }),
    enabled: open,
  });
  const items = history.data?.items ?? [];
  return (
    <div className="set-row" style={{ display: "block" }}>
      <div className="flex items-start gap-3">
        <span className="min-w-0 flex-1">
          <span className="set-row-title block">Comment history</span>
          <span className="set-row-sub block">Every comment you&apos;ve written on Feed posts, newest first. Comments live here in Settings — they never show on your profile.</span>
        </span>
        <button type="button" className="btn-ghost flex-none" style={{ minHeight: 38, padding: "5px 12px", fontSize: 13 }} onClick={() => setOpen((v) => !v)} aria-expanded={open} aria-label={open ? "Hide your comment history" : "Show your comment history"}>
          {open ? "Hide" : "Show"}
        </button>
      </div>
      {open && (
        <div className="mt-3">
          {history.isPending && <p className="text-sm text-[var(--dim)]" role="status">Loading your comments…</p>}
          {history.data && items.length === 0 && (
            <p className="text-sm leading-relaxed text-[var(--dim)]">You haven&apos;t commented on any post yet — when you do, your comments collect here.</p>
          )}
          {items.length > 0 && (
            <ul className="grid gap-2.5">
              {items.map((c) => (
                <li key={c.id} className="rounded-xl border border-[var(--border)] bg-[var(--surface2)] px-3.5 py-3">
                  <p className="whitespace-pre-line text-[14px] leading-relaxed [overflow-wrap:anywhere]">{c.body}</p>
                  <p className="mt-1.5 text-[12.5px] text-[var(--dim)]">
                    On {c.postAuthor ? <><strong className="text-[var(--text)]">{c.postAuthor}</strong>&apos;s post</> : "a post"}{c.postTitle ? <> — &ldquo;{c.postTitle}&rdquo;</> : ""} · {new Date(c.createdAt).toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" })}
                  </p>
                </li>
              ))}
            </ul>
          )}
        </div>
      )}
    </div>
  );
}

type SettingsSection =
  | "general" | "connectors" | "wallet" | "secure" | "permissions"
  | "messaging" | "devices" | "data" | "help" | "legal" | "logout";

// X-style Settings structure, trimmed to what ViceSunshine actually
// has: Your account / Premium & wallet / Security and account access /
// Connected accounts / Privacy and safety / Notifications / Devices &
// sessions / Data controls / Additional resources (the legal pages) /
// Help & support. No Sports, no Grok, no Creator Studio — nothing
// ViceSunshine does not have. Section ids are unchanged so every
// existing openSettings(...) caller keeps landing in the right place.
