  "street-heat": { title: "STREET HEAT", tagline: "Asphalt & fire", accent: "#FF8A3D", scene: "flames", animated: false, background: "radial-gradient(90% 130% at 85% 110%,#FFD166 0%,#FF7A00 34%,transparent 62%), linear-gradient(100deg,#160503 0%,#3d0d02 45%,#8E2434 100%)" },
  "palm-reaper": { title: "PALM REAPER", tagline: "Death by the beach", accent: "#E8F4FF", scene: "skullpalms", animated: false, background: "radial-gradient(60% 90% at 82% 20%,rgba(232,244,255,0.85) 0%,transparent 42%), linear-gradient(100deg,#050508 0%,#141422 55%,#3b1470 115%)" },
  "keys-runner": { title: "KEYS RUNNER", tagline: "Causeway speed demon", accent: "#19E3C2", scene: "speed", animated: false, background: "linear-gradient(100deg,#02141a 0%,#06333d 40%,#0e7d74 75%,#19E3C2 125%), repeating-linear-gradient(100deg,transparent 0 34px,rgba(255,255,255,0.06) 34px 36px)" },
  "skull-strip": { title: "SKULL STRIP", tagline: "A wall of the fallen", accent: "#FF2E88", scene: "skulls", animated: false, background: "radial-gradient(50% 90% at 12% 50%,rgba(255,46,136,0.6) 0%,transparent 55%), repeating-linear-gradient(90deg,#0a0a0f 0 30px,#17171f 30px 60px)" },
  "leonida-haze": { title: "VICE HAZE", tagline: "Green over Leonida", accent: "#7BE382", scene: "haze", animated: true, background: "radial-gradient(75% 120% at 22% 115%,rgba(123,227,130,0.55) 0%,transparent 55%), radial-gradient(60% 100% at 78% -10%,rgba(57,224,122,0.4) 0%,transparent 55%), linear-gradient(100deg,#030b05 0%,#08270f 55%,#0d3b26 100%)" },
  "armed-palms": { title: "HYDRO VICE", tagline: "Grown in the neon dark", accent: "#39E07A", scene: "hydro", animated: true, background: "radial-gradient(70% 120% at 80% 50%,rgba(57,224,122,0.35) 0%,transparent 60%), linear-gradient(100deg,#020805 0%,#0a2417 60%,#04140a 100%)" },
  "club-leonida": { title: "MAGIC PALMS", tagline: "Skull magic, Vice style", accent: "#FFB03A", scene: "magic", animated: true, background: "radial-gradient(70% 120% at 85% 110%,rgba(255,122,0,0.55) 0%,transparent 55%), linear-gradient(100deg,#0d0212 0%,#2A1454 55%,#12041f 100%)" },
  "dead-palms": { title: "DEAD PALMS", tagline: "The undead own the night", accent: "#39E07A", scene: "deadpalms", animated: true, background: "radial-gradient(65% 100% at 80% 15%,rgba(57,224,122,0.4) 0%,transparent 50%), linear-gradient(100deg,#020d06 0%,#0a2e17 50%,#123f1e 100%)" },
  "inferno": { title: "INFERNO", tagline: "The whole strip burns", accent: "#FF7A00", scene: "inferno", animated: true, background: "radial-gradient(100% 140% at 50% 125%,#FFE9A8 0%,#FFB03A 26%,#FF5E00 52%,#8E2434 82%,#1a0300 100%)" },
  "clan-vice": { title: "VICE NIGHTS", tagline: "Neon never sleeps", accent: "#FF2E88", scene: "skyline", animated: false, background: "linear-gradient(100deg,#0b0618 0%,#2b0a3a 30%,#FF2E88 62%,#19E3C2 130%), repeating-linear-gradient(115deg,transparent 0 26px,rgba(255,255,255,0.05) 26px 27px)" },
  "clan-heat": { title: "STREET HEAT", tagline: "Asphalt & fire", accent: "#FF8A3D", scene: "flames", animated: false, background: "radial-gradient(90% 130% at 85% 110%,#FFD166 0%,#FF7A00 34%,transparent 62%), linear-gradient(100deg,#160503 0%,#3d0d02 45%,#8E2434 100%)" },
  "clan-haze": { title: "VICE HAZE", tagline: "Green over Leonida", accent: "#7BE382", scene: "haze", animated: true, background: "radial-gradient(75% 120% at 22% 115%,rgba(123,227,130,0.55) 0%,transparent 55%), radial-gradient(60% 100% at 78% -10%,rgba(57,224,122,0.4) 0%,transparent 55%), linear-gradient(100deg,#030b05 0%,#08270f 55%,#0d3b26 100%)" },
