      setRegion(p.region);
      setPlaystyle(p.playstyle || "Chill");
      setPsnId(p.psnId);
      setXboxId(p.xboxId);
      setRockstarId(p.rockstarId);
      setDiscordId(p.discordId);
      setOthers(p.others);
      setShowPsn(p.showPsn);
      setShowXbox(p.showXbox);
      setShowRockstar(p.showRockstar);
      setShowDiscord(p.showDiscord);
      setShowOther(p.showOther);
