  // profile and in Linked accounts, and the honest pending /
  // active lines — the server only ever reports the role as
  // active after the Discord bot has confirmed it.
  const discordRole = useQuery({
    queryKey: ["discord-role", playerKey],
    queryFn: () => api.getDiscordRoleStatus({ playerKey }),
    enabled: Boolean(me?.premium),
  });
  const discordRoleState = me?.premium ? discordRole.data : undefined;
  // Self-heal for pre-optimizer profile photos (see
